  green: "var(--mh-green)", greenSubtle: "var(--mh-green-subtle)", greenBorder: "var(--mh-green-border)",
  greenShadow: "var(--mh-green-shadow)",
  bg: "var(--mh-bg)", surface: "var(--mh-surface)", surfaceRaised: "var(--mh-surface-raised)",
