// ── Admin section pages (Recruiting / Marketing / Resources) ──────────────────
// These render raw sheet tabs served by /api/athletes?tab=… so the UI always
// matches whatever columns the sheet actually has.
const adminTabCache = {};
// One request per tab at a time: a profile's prefetch and the tabs that
// mount while it's in flight share it instead of each fetching.
const adminTabInflight = {};
function fetchAdminTab(key, api = 'athletes', fresh = false) {
  const ck = `${api}:${key}`;
  if (!fresh && adminTabInflight[ck]) return adminTabInflight[ck];
  const pr = fetch(`/api/${api}?tab=${key}${fresh ? '&fresh=1' : ''}`)
    .then(r => r.json())
    .then(d => { if (d.error) throw new Error(d.error); adminTabCache[ck] = d; return d; })
    .finally(() => { if (adminTabInflight[ck] === pr) delete adminTabInflight[ck]; });
  adminTabInflight[ck] = pr;
  return pr;
}
const prefetchAdminTab = (key, api = 'athletes') => { if (!adminTabCache[`${api}:${key}`]) fetchAdminTab(key, api).catch(() => {}); };
function useAdminTab(key, api = 'athletes', enabled = true) {
  // Serve the last fetch instantly on remount (no loading flash when hopping
  // between pages) and refresh quietly in the background. `api` picks the
  // endpoint: 'athletes' (sports sheet tabs) or 'sheets' (music sheet tabs).
  const ck = `${api}:${key}`;
  const [data, setData] = useState(() => adminTabCache[ck] || null);
  const [err, setErr] = useState(null);
  const [loading, setLoading] = useState(!adminTabCache[ck]);
  const load = useCallback((fresh) => {
    if (!enabled) return;
    if (!adminTabCache[ck]) setLoading(true);
    // fresh=1 bypasses the server's 60s sheet cache — used for the reload
    // right after a write so the writer always sees their own change.
    fetchAdminTab(key, api, !!fresh)
      .then(d => { setData(d); setErr(null); })
      .catch(e => setErr(e.message))
      .finally(() => setLoading(false));
  }, [key, api, ck, enabled]);
  useEffect(() => { load(); }, [load]);
  // Multi-user freshness: another agent's edit shows up when this tab regains
  // focus, or within a few minutes if the view just stays open.
  useEffect(() => {
    const onVis = () => { if (document.visibilityState === 'visible') load(); };
    document.addEventListener('visibilitychange', onVis);
    const t = setInterval(() => { if (document.visibilityState === 'visible') load(); }, 3 * 60 * 1000);
    return () => { document.removeEventListener('visibilitychange', onVis); clearInterval(t); };
  }, [load]);
  return { data, err, loading, reload: () => load(true) };
}

function SheetTable({ headers, rows, onRowClick, emptyMsg, renderCell }) {
  if (!rows.length) return <div style={{ padding: "28px 16px", color: G.textTertiary, fontSize: 13, textAlign: "center" }}>{emptyMsg || 'Nothing here yet.'}</div>;
  return (
    <div className="mh-hscroll" style={{ overflowX: "auto" }}>
      <table style={{ borderCollapse: "collapse", width: "100%" }}>
        <thead><tr>
          {headers.map((h, i) => (
            <th key={i} style={{ textAlign: "left", padding: "10px 14px", fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em", color: G.textTertiary, borderBottom: `1px solid ${G.surfaceBorder}`, whiteSpace: "nowrap" }}>{h}</th>
          ))}
        </tr></thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r._row} onClick={onRowClick ? () => onRowClick(r) : undefined}
              style={{ cursor: onRowClick ? "pointer" : "default" }}
              onMouseEnter={e => { e.currentTarget.style.background = G.surfaceRaised; }}
              onMouseLeave={e => { e.currentTarget.style.background = "transparent"; }}>
              {r.cells.map((c, j) => (
                <td key={j} style={{ padding: "10px 14px", fontSize: 13, color: j === 0 ? G.text : G.textSecondary, fontWeight: j === 0 ? 600 : 400, borderBottom: `1px solid ${G.surfaceBorder}`, whiteSpace: "nowrap", maxWidth: 260, overflow: "hidden", textOverflow: "ellipsis" }}>{renderCell ? renderCell(c, headers[j]) : c}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// Edit/add modal for a sheet-tab row: one field per column, notes get a textarea.
function TabRowForm({ headers, initial, onSave, onDelete, onCancel, title, selects = {} }) {
  const [vals, setVals] = useState(() => {
    const o = {};
    headers.forEach((h, i) => { o[h] = initial ? (initial.cells[i] || '') : ''; });
    return o;
  });
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, []);
  const save = async () => {
    setBusy(true);
    try { await onSave(vals); } catch (e) { alert(e.message || 'Save failed'); } finally { setBusy(false); }
  };
  const del = async () => {
    if (!window.confirm("Remove this row from the sheet? This can't be undone.")) return;
    setBusy(true);
    try { await onDelete(); } catch (e) { alert(e.message || 'Remove failed'); } finally { setBusy(false); }
  };
  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 100, background: "rgba(0,0,0,0.7)", backdropFilter: "blur(4px)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={onCancel}>
      <div onClick={e => e.stopPropagation()} style={{ background: G.surface, border: `1px solid ${G.surfaceBorderLight}`, borderRadius: 16, width: "100%", maxWidth: 560, maxHeight: "86vh", overflowY: "auto", padding: 20, animation: "modalIn .18s ease" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
          <div style={{ fontWeight: 800, fontSize: 17, color: G.text, letterSpacing: "-0.02em" }}>{title}</div>
          <button onClick={onCancel} style={{ background: G.surfaceRaised, border: `1px solid ${G.surfaceBorder}`, borderRadius: 10, color: G.textSecondary, cursor: "pointer", padding: "6px 11px", fontSize: 14, fontFamily: ff }}>✕</button>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
          {headers.map(h => {
            const isNote = /note|comment/i.test(h);
            const opts = selects[h.trim().toLowerCase()];
            return (
              <div key={h} style={{ gridColumn: isNote ? "1 / -1" : "auto" }}>
                <label style={labelStyle}>{h}</label>
                {opts
                  ? <select value={vals[h]} onChange={e => setVals(v => ({ ...v, [h]: e.target.value }))} style={{ ...inputBase, cursor: "pointer" }}>
                      <option value="">—</option>
                      {opts.map(o => <option key={o} value={o}>{o}</option>)}
                    </select>
                  : isNote
                  ? <textarea value={vals[h]} onChange={e => setVals(v => ({ ...v, [h]: e.target.value }))} rows={3} style={{ ...inputBase, resize: "vertical" }} />
                  : <input value={vals[h]} onChange={e => setVals(v => ({ ...v, [h]: e.target.value }))} style={inputBase} />}
              </div>
            );
          })}
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
          {initial && onDelete && (
            <button onClick={del} disabled={busy} style={{ background: "transparent", border: "1px solid rgba(220,38,38,0.4)", borderRadius: 12, padding: "11px 14px", color: G.red, fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: ff }}>Remove</button>
          )}
          <button onClick={onCancel} style={{ flex: 1, background: G.surfaceRaised, border: `1px solid ${G.surfaceBorder}`, borderRadius: 12, padding: "11px", color: G.textSecondary, fontWeight: 600, fontSize: 14, cursor: "pointer", fontFamily: ff }}>Cancel</button>
          <button onClick={save} disabled={busy} style={{ flex: 2, background: busy ? G.surfaceRaised : G.green, border: "none", borderRadius: 12, padding: "11px", color: busy ? G.textTertiary : "#0a0a0a", fontWeight: 700, fontSize: 14, cursor: busy ? "wait" : "pointer", fontFamily: ff }}>{busy ? 'Saving…' : 'Save'}</button>
        </div>
      </div>
    </div>
  );
}

// Recruiting pipeline stages, in order. Signed unlocks the one-click upgrade
// that creates the recruit as a roster client.
const REC_STAGES = ['Outreach', 'Consistent Contact', 'Signed', 'Signed Elsewhere'];
// Literal hexes (not theme vars): the stage select derives its border by
// appending an alpha byte, which only works on a real hex. These read fine on
// both themes.
const stageColor = (s) => s === 'Signed' ? '#3eaa78' : s === 'Consistent Contact' ? '#d97706' : s === 'Signed Elsewhere' ? '#dc2626' : '#8a8a98';
// Same normalization the onboarding merge uses — so "Jr." vs "Jr" or stray
// punctuation can't make the board think a rostered player isn't a client yet.
const nameKey = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();

// Uniform recruit inputs: every field that has a known value set is a select.
const REC_POSITIONS = ['QB', 'RB', 'FB', 'WR', 'TE', 'OT', 'OG', 'C', 'OL', 'EDGE', 'DE', 'DT', 'DL', 'LB', 'CB', 'S', 'DB', 'ATH', 'K', 'P', 'LS'];
const REC_COLLEGE_CLASSES = ['Freshman', 'RS Freshman', 'Sophomore', 'RS Sophomore', 'Junior', 'RS Junior', 'Senior', 'RS Senior', 'Graduate'];
const REC_RATINGS = ['5-star', '4-star', '3-star', '2-star'];
const recHsClasses = () => { const y = new Date().getFullYear(); return [y, y + 1, y + 2, y + 3, y + 4].map(String); };
// Display normalizers for legacy hand-entered values ("RS JR" → "RS Junior",
// "3 Star" → "3-star"). The nightly sync rewrites linked rows at the source.
const prettyClass = (v) => {
  const s = String(v || '').trim();
  const yy = s.match(/^'?(2\d)$/);
  if (yy) return '20' + yy[1]; // "27" / "'28" → full grad year
  const M = { fr: 'Freshman', fresh: 'Freshman', freshman: 'Freshman', so: 'Sophomore', soph: 'Sophomore', sophmore: 'Sophomore', sopmore: 'Sophomore', sophomore: 'Sophomore', jr: 'Junior', junior: 'Junior', sr: 'Senior', senior: 'Senior', gr: 'Graduate', grad: 'Graduate', graduate: 'Graduate' };
  const m = s.toLowerCase().match(/^(rs\s*[- ]?)?\s*([a-z]+)\.?$/);
  if (!m || !M[m[2]]) return s;
  return (m[1] ? 'RS ' : '') + M[m[2]];
};
const prettyRating = (v) => {
  const s = String(v || '').trim();
  if (/^(un\s*ranked|unranked|unrated|unanked|[-—–]+)$/i.test(s)) return '';
  return s.replace(/^(\d)\s*[- ]*\s*star$/i, '$1-star');
};

// Multi-select dropdown, same mechanics as the board's filter menu: a quiet
// select-looking trigger that opens a checklist — click entries to toggle,
// click outside to close. Value is stored as the joined string the sheet uses.
function MultiPick({ value, onChange, options, splitRe = /\n/, joiner = '', single = false, placeholder = '—' }) {
  const [open, setOpen] = useState(false);
  const ref = useRef();
  useEffect(() => {
    const h = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, []);
  const cur = single
    ? (String(value || '').trim() ? [String(value).trim()] : [])
    : String(value || '').split(splitRe).map(s => s.trim()).filter(Boolean);
  const all = [...new Set([...options, ...cur])]; // legacy values stay listed
  const toggle = (o) => {
    if (single) { onChange(cur.includes(o) ? '' : o); setOpen(false); return; }
    const next = cur.includes(o) ? cur.filter(x => x !== o) : [...cur, o];
    onChange(next.join(joiner));
  };
  return (
    <div ref={ref} style={{ position: "relative" }}>
      <button type="button" onClick={() => setOpen(v => !v)}
        style={{ ...inputBase, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, cursor: "pointer", textAlign: "left", width: "100%" }}>
        <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", color: cur.length ? G.text : G.textTertiary }}>{cur.length ? cur.join(joiner) : placeholder}</span>
        <span style={{ fontSize: 9, opacity: 0.6, flexShrink: 0, transform: open ? 'rotate(180deg)' : 'none', transition: `transform 0.15s ${G.ease}` }}>▾</span>
      </button>
      {open && (
        <div style={{ position: "absolute", top: "calc(100% + 6px)", left: 0, right: 0, maxHeight: 230, overflowY: "auto", background: G.surfaceGlass, backdropFilter: "blur(20px)", WebkitBackdropFilter: "blur(20px)", border: `1px solid ${G.surfaceBorderLight}`, borderRadius: 12, padding: 6, zIndex: 600, boxShadow: G.shadowLg }}>
          {all.map(o => {
            const on = cur.includes(o);
            return (
              <button key={o} type="button" onClick={() => toggle(o)}
                style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, padding: "8px 12px", background: "transparent", border: "none", borderRadius: 8, cursor: "pointer", fontFamily: ff, fontSize: 13, fontWeight: on ? 700 : 400, color: on ? G.green : G.text, textAlign: "left" }}
                onMouseEnter={e => e.currentTarget.style.background = G.surfaceRaised}
                onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                {o}
                {on && <span style={{ color: G.green, fontSize: 12 }}>✓</span>}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

// Add/edit form for the recruiting board. Add mode leads with the lookup:
// pick the level, type a name (+ school to disambiguate), hit Find profile,
// tap the right match — position, school, class, rating and photo fill in and
// the row stays linked so the nightly sync keeps it fresh. No match → the
// same form works fully manually.
function RecruitForm({ headers, initial, defaultLevel, staff, onSave, onDelete, onCancel }) {
  const hOf = (re) => headers.find(h => re.test(h)) || null;
  const H = {
    name: hOf(/player\s*name|^name/i), school: hOf(/school/i), level: hOf(/^level/i),
    pos: hOf(/position/i), rank: hOf(/rank/i), klass: hOf(/class|year/i),
    agent: hOf(/agent/i), notes: hOf(/note|comment/i), stage: hOf(/^stage/i),
    espnId: hOf(/^espnid/i), url247: hOf(/^url247/i), photo: hOf(/^photo/i), film: hOf(/^film/i),
  };
  const cell = (h) => (initial && h) ? (initial.cells[headers.indexOf(h)] || '') : '';
  const rawLevel = cell(H.level);
  const [level, setLevel] = useState(rawLevel ? (/college/i.test(rawLevel) ? 'College' : 'High School') : (defaultLevel || 'High School'));
  const [f, setF] = useState({
    name: cell(H.name), school: cell(H.school), pos: cell(H.pos).toUpperCase(),
    rank: prettyRating(cell(H.rank)), klass: cell(H.klass), agent: cell(H.agent),
    notes: cell(H.notes), stage: cell(H.stage),
    espnId: cell(H.espnId), url247: cell(H.url247), photo: cell(H.photo), film: cell(H.film),
  });
  const set = (k) => (e) => setF(v => ({ ...v, [k]: e.target.value }));
  const linked = level === 'College' ? !!f.espnId : !!f.url247;
  const [searching, setSearching] = useState(false);
  const [cands, setCands] = useState(null); // null = not searched yet; [] = nothing found
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, []);
  const doSearch = async () => {
    if (!f.name.trim()) { alert('Enter the player\'s name first.'); return; }
    setSearching(true); setCands(null);
    try {
      const r = await fetch('/api/athletes', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'recruit-search', name: f.name.trim(), school: f.school.trim(), level, classOf: level === 'High School' ? f.klass : undefined }),
      });
      const d = await r.json();
      if (!r.ok || d.error) throw new Error(d.error || 'Search failed');
      setCands(d.candidates || []);
    } catch (e) { alert(e.message || 'Search failed'); }
    finally { setSearching(false); }
  };
  const pickCand = (c) => {
    setF(v => ({
      ...v,
      name: c.name || v.name, school: c.school || v.school,
      pos: (c.position || v.pos).toUpperCase(), klass: c.classYear || v.klass,
      rank: c.stars ? `${c.stars}-star` : v.rank, photo: c.photo || v.photo,
      espnId: c.espnId || '', url247: c.url247 || '',
    }));
    setCands(null);
  };
  const unlink = () => setF(v => ({ ...v, espnId: '', url247: '', photo: '' }));
  const save = async () => {
    if (!f.name.trim()) { alert('Name is required.'); return; }
    setBusy(true);
    try {
      const vals = {};
      const put = (h, v) => { if (h) vals[h] = v; };
      put(H.name, f.name.trim()); put(H.school, f.school.trim()); put(H.level, level);
      put(H.pos, f.pos); put(H.rank, f.rank); put(H.klass, f.klass);
      put(H.agent, f.agent); put(H.notes, f.notes); put(H.stage, f.stage);
      put(H.espnId, f.espnId); put(H.url247, f.url247); put(H.photo, f.photo);
      if (level === 'High School') put(H.film, f.film.trim());
      await onSave(vals);
    } catch (e) { alert(e.message || 'Save failed'); }
    finally { setBusy(false); }
  };
  const del = async () => {
    if (!window.confirm("Remove this recruit from the board? This can't be undone.")) return;
    setBusy(true);
    try { await onDelete(); } catch (e) { alert(e.message || 'Remove failed'); } finally { setBusy(false); }
  };
  // Selects keep unusual legacy values selectable instead of blanking them.
  const withCurrent = (opts, cur) => [...new Set([...(cur ? [cur] : []), ...opts])];
  const classOpts = withCurrent(level === 'College' ? REC_COLLEGE_CLASSES : recHsClasses(), f.klass);
  const rankOpts = withCurrent(REC_RATINGS, f.rank);
  const sourceLabel = level === 'College' ? 'ESPN' : '247Sports';
  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 100, background: "rgba(0,0,0,0.7)", backdropFilter: "blur(4px)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={onCancel}>
      <div onClick={e => e.stopPropagation()} style={{ background: G.surface, border: `1px solid ${G.surfaceBorderLight}`, borderRadius: 16, width: "100%", maxWidth: 560, maxHeight: "86vh", overflowY: "auto", padding: 20, animation: "modalIn .18s ease" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
          <div style={{ fontWeight: 800, fontSize: 17, color: G.text, letterSpacing: "-0.02em" }}>{initial ? (f.name || 'Edit recruit') : 'Add recruit'}</div>
          <button onClick={onCancel} style={{ background: G.surfaceRaised, border: `1px solid ${G.surfaceBorder}`, borderRadius: 10, color: G.textSecondary, cursor: "pointer", padding: "6px 11px", fontSize: 14, fontFamily: ff }}>✕</button>
        </div>
        {/* Level toggle */}
        <div style={{ display: "flex", gap: 6, marginBottom: 14 }}>
          {['High School', 'College'].map(lv => (
            <button key={lv} onClick={() => { if (level !== lv) { setLevel(lv); setCands(null); unlink(); setF(v => ({ ...v, klass: '' })); } }}
              style={{ flex: 1, background: level === lv ? G.greenSubtle : G.surfaceRaised, border: `1px solid ${level === lv ? G.green : G.surfaceBorder}`, borderRadius: 10, padding: "9px 0", color: level === lv ? G.green : G.textSecondary, fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: ff }}>
              {lv}
            </button>
          ))}
        </div>
        {/* Name + school + lookup */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
          <div>
            <label style={labelStyle}>Player name</label>
            <input value={f.name} onChange={set('name')} placeholder="First Last" style={inputBase}
              onKeyDown={e => { if (e.key === 'Enter') doSearch(); }} />
          </div>
          <div>
            <label style={labelStyle}>School</label>
            <input value={f.school} onChange={set('school')} placeholder={level === 'College' ? 'e.g. Ohio State' : 'e.g. Moeller HS'} style={inputBase}
              onKeyDown={e => { if (e.key === 'Enter') doSearch(); }} />
          </div>
        </div>
        {linked ? (
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 12, background: G.greenSubtle, border: `1px solid ${G.green}44`, borderRadius: 12, padding: "9px 12px" }}>
            <Avatar name={f.name} photoUrl={f.photo} size={34} />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 12.5, fontWeight: 700, color: G.green }}>Linked to {sourceLabel} ✓</div>
              <div style={{ fontSize: 11, color: G.textTertiary }}>Profile syncs automatically every night</div>
            </div>
            <button onClick={unlink} style={{ background: "transparent", border: `1px solid ${G.surfaceBorder}`, borderRadius: 8, padding: "5px 10px", color: G.textTertiary, fontSize: 11.5, fontWeight: 600, cursor: "pointer", fontFamily: ff }}>Unlink</button>
          </div>
        ) : (
          <div style={{ marginTop: 12 }}>
            <button onClick={doSearch} disabled={searching}
              style={{ width: "100%", background: G.surfaceRaised, border: `1px dashed ${G.surfaceBorderLight}`, borderRadius: 12, padding: "10px", color: searching ? G.textTertiary : G.text, fontWeight: 700, fontSize: 13, cursor: searching ? 'wait' : 'pointer', fontFamily: ff }}>
              {searching ? 'Searching…' : `🔍 Find ${sourceLabel} profile`}
            </button>
            {cands !== null && (cands.length === 0
              ? <div style={{ marginTop: 8, fontSize: 12, color: G.textTertiary, textAlign: "center" }}>No {sourceLabel} profile found — fill in the details below.</div>
              : (
                <div style={{ marginTop: 8, border: `1px solid ${G.surfaceBorder}`, borderRadius: 12, overflow: "hidden" }}>
                  {cands.map((c, i) => (
                    <div key={c.espnId || c.url247 || i} onClick={() => pickCand(c)}
                      style={{ display: "flex", alignItems: "center", gap: 10, padding: "9px 12px", cursor: "pointer", borderBottom: i < cands.length - 1 ? `1px solid ${G.surfaceBorder}` : "none" }}
                      onMouseEnter={e => e.currentTarget.style.background = G.surfaceRaised}
                      onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                      <Avatar name={c.name} photoUrl={c.photo} size={34} />
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontSize: 13, fontWeight: 700, color: G.text }}>{c.name}</div>
                        <div style={{ fontSize: 11.5, color: G.textSecondary, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                          {[c.school, c.position, level === 'College' ? c.classYear : `Class of ${c.classYear}`, c.stars ? `${c.stars}★` : ''].filter(Boolean).join(' · ')}
                        </div>
                      </div>
                      <span style={{ fontSize: 11.5, fontWeight: 700, color: G.green, flexShrink: 0 }}>Use →</span>
                    </div>
                  ))}
                </div>
              ))}
          </div>
        )}
        {/* Detail fields — selects everywhere a value set is known */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginTop: 14 }}>
          <div><label style={labelStyle}>Position</label><MultiPick value={f.pos} onChange={v => setF(x => ({ ...x, pos: v }))} options={REC_POSITIONS} splitRe={/[\/,]+/} joiner="/" /></div>
          <div><label style={labelStyle}>Agent</label><MultiPick value={f.agent} onChange={v => setF(x => ({ ...x, agent: v }))} options={staff || []} splitRe={/,/} joiner=", " /></div>
          <div><label style={labelStyle}>{level === 'College' ? 'Class' : 'Graduating class'}</label><MultiPick single value={f.klass} onChange={v => setF(x => ({ ...x, klass: v }))} options={classOpts} /></div>
          <div><label style={labelStyle}>Rating</label><MultiPick single value={f.rank} onChange={v => setF(x => ({ ...x, rank: v }))} options={rankOpts} placeholder="Unrated" /></div>
          <div><label style={labelStyle}>Stage</label><MultiPick single value={f.stage} onChange={v => setF(x => ({ ...x, stage: v }))} options={REC_STAGES} /></div>
          {level === 'High School' && (
            <div style={{ gridColumn: "1 / -1" }}>
              <label style={labelStyle}>Hudl / film link</label>
              <input value={f.film} onChange={set('film')} placeholder="https://www.hudl.com/profile/…" style={inputBase} />
            </div>
          )}
          <div style={{ gridColumn: "1 / -1" }}>
            <label style={labelStyle}>Notes</label>
            <textarea value={f.notes} onChange={set('notes')} rows={3} style={{ ...inputBase, resize: "vertical" }} />
          </div>
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
          {initial && onDelete && (
            <button onClick={del} disabled={busy} style={{ background: "transparent", border: "1px solid rgba(220,38,38,0.4)", borderRadius: 12, padding: "11px 14px", color: G.red, fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: ff }}>Remove</button>
          )}
          <button onClick={onCancel} style={{ flex: 1, background: G.surfaceRaised, border: `1px solid ${G.surfaceBorder}`, borderRadius: 12, padding: "11px", color: G.textSecondary, fontWeight: 600, fontSize: 14, cursor: "pointer", fontFamily: ff }}>Cancel</button>
          <button onClick={save} disabled={busy} style={{ flex: 2, background: busy ? G.surfaceRaised : G.green, border: "none", borderRadius: 12, padding: "11px", color: busy ? G.textTertiary : "#0a0a0a", fontWeight: 700, fontSize: 14, cursor: busy ? "wait" : "pointer", fontFamily: ff }}>{busy ? 'Saving…' : 'Save'}</button>
        </div>
      </div>
    </div>
  );
}

// ── Prospect Search (sports) ──────────────────────────────────────────────────
// Every FBS + FCS player (CollegeFootballData, rebuilt weekly by
// api/prospects.js) in one gzipped file the browser unpacks and filters
// locally — ~31k rows filter in milliseconds, no per-search API calls.
const PROSPECTS = { data: null, promise: null, building: false };
const PX_POS_GROUPS = [
  ['QB', ['QB', 'PRO', 'DUAL']], ['RB', ['RB', 'FB', 'APB']], ['WR', ['WR']], ['TE', ['TE']],
  ['OL', ['OL', 'OT', 'OG', 'C', 'G', 'T', 'IOL']], ['DL', ['DL', 'DE', 'DT', 'NT', 'EDGE', 'SDE', 'WDE', 'IDL']],
  ['LB', ['LB', 'ILB', 'OLB', 'MLB']], ['DB', ['DB', 'CB', 'S', 'FS', 'SS', 'SAF']],
  ['K/P', ['K', 'P', 'PK', 'LS']], ['ATH', ['ATH']],
];
const pxGroupOf = (pos) => (PX_POS_GROUPS.find(([, l]) => l.includes(String(pos || '').toUpperCase())) || [''])[0];
const PX_CLASS = { 1: 'FR', 2: 'SO', 3: 'JR', 4: 'SR', 5: '5th+' };
const PX_TIERS = [['P4', 'Power 4'], ['G5', 'Group of 5'], ['FCS', 'FCS'], ['D2', 'D2']];
const pxHt = (inches) => inches ? `${Math.floor(inches / 12)}'${inches % 12}"` : '';
const PX_STATS = [
  ['rec', 'Receptions'], ['recYds', 'Receiving yards'], ['recTd', 'Receiving TDs'],
  ['rushAtt', 'Carries'], ['rushYds', 'Rushing yards'], ['rushTd', 'Rushing TDs'],
  ['passYds', 'Passing yards'], ['passTd', 'Passing TDs'], ['passCmp', 'Completions'], ['passInt', 'INTs thrown'],
  ['tkl', 'Tackles'], ['solo', 'Solo tackles'], ['tfl', 'Tackles for loss'], ['sacks', 'Sacks'],
  ['int', 'Interceptions'], ['pd', 'Passes defended'], ['qbh', 'QB hurries'],
  ['fgm', 'Field goals made'], ['punts', 'Punts'],
];
const PX_STAT_LABEL = Object.fromEntries(PX_STATS);
const PX_DEFAULT_SORT = { QB: 'passYds', RB: 'rushYds', WR: 'recYds', TE: 'recYds', DL: 'sacks', LB: 'tkl', DB: 'tkl', 'K/P': 'fgm' };
const PX_EMPTY = { q: '', team: '', groups: [], tiers: [], conf: '', classes: [], htMin: 0, htMax: 0, wtMin: '', wtMax: '', st: '', near: '', miles: 0, hs: '', stars: 0, spTop: 0, scope: 'season', rules: [], cols: null, outperf: false };
// ── Production score ─────────────────────────────────────────────────────────
// Rebuilt 2026-09-30 after two flaws in the first version (season-total
// volume): corners scored mostly on tackles (being thrown at), and punters on
// punt count (a bad offense). Now:
//  • players are compared within their TRUE position (CB vs CB, S vs S, edge
//    vs DT, K vs P), and only once they've played enough to judge;
//  • counting stats are per team game played;
//  • offense leans on efficiency (expected points added per play, CFBD) and
//    role (share of team plays);
//  • each stat becomes a percentile within the position, and the score is
//    the weighted average of those (corners: breakups + INTs, not tackles) —
//    so one extreme number can only move it as far as its weight allows;
//  • the final percentile is the rank of that blend within the position.
// Offensive linemen have no individual stats in any free source — no score.
const PX_BUCKET = { PRO: 'QB', DUAL: 'QB', APB: 'RB', SDE: 'EDGE', WDE: 'EDGE', IDL: 'DT', QB: 'QB', RB: 'RB', FB: 'RB', WR: 'WR', TE: 'TE', CB: 'CB', S: 'S', FS: 'S', SS: 'S', SAF: 'S', DB: 'DB', LB: 'LB', ILB: 'LB', MLB: 'LB', OLB: 'LB', DE: 'EDGE', EDGE: 'EDGE', DT: 'DT', NT: 'DT', DL: 'DL', K: 'K', PK: 'K', P: 'P', ATH: 'ATH' };
const PX_BUCKET_LABEL = { QB: 'quarterbacks', RB: 'running backs', WR: 'receivers', TE: 'tight ends', CB: 'cornerbacks', S: 'safeties', DB: 'defensive backs', LB: 'linebackers', EDGE: 'edge rushers', DT: 'defensive tackles', DL: 'defensive linemen', K: 'kickers', P: 'punters', ATH: 'athletes' };
const pxF1 = (v) => v.toFixed(1), pxF2 = (v) => v.toFixed(2), pxPctF = (v) => `${Math.round(v * 100)}%`;
const pxPerG = (k) => (p, s, gp) => s(k) / gp;
// Efficiency only counts with enough plays behind it (CFBD has records that
// rest on one play); below that it's left out and the other stats decide.
const pxEff = (i, minPlays) => (p) => (!p.ppa || (p.ppa[3] || 0) < minPlays ? null : (p.ppa[i] != null ? p.ppa[i] : p.ppa[0]));
const pxRole = (p) => (p.usage ? p.usage[0] : null);
const PX_RECV = [['Efficiency (points added per play)', 2.5, pxEff(0, 12), pxF2], ['Receiving yds per game', 1.5, pxPerG('recYds'), pxF1], ['Receiving TDs per game', 1, pxPerG('recTd'), pxF2], ['Share of team plays', 1, pxRole, pxPctF]];
const PX_SCORE_DEFS = {
  QB: { min: 'at least 30 pass attempts', ok: (s) => s('passAtt') >= 30, parts: [['Efficiency (points added per dropback)', 3, pxEff(1, 40), pxF2], ['Passing yds per game', 1.5, pxPerG('passYds'), pxF1], ['Passing TDs per game', 1, pxPerG('passTd'), pxF2], ['INTs thrown per game', -1.5, pxPerG('passInt'), pxF2], ['Rushing yds per game', 0.5, pxPerG('rushYds'), pxF1]] },
  RB: { min: 'at least 20 carries', ok: (s) => s('rushAtt') >= 20, parts: [['Efficiency (points added per play)', 2.5, pxEff(0, 30), pxF2], ['Scrimmage yds per game', 1.5, (p, s, gp) => (s('rushYds') + s('recYds')) / gp, pxF1], ['TDs per game', 1, (p, s, gp) => (s('rushTd') + s('recTd')) / gp, pxF2], ['Share of team plays', 1, pxRole, pxPctF]] },
  WR: { min: 'at least 8 catches', ok: (s) => s('rec') >= 8, parts: PX_RECV },
  TE: { min: 'at least 5 catches', ok: (s) => s('rec') >= 5, parts: PX_RECV },
  CB: { min: '6+ tackles and breakups', ok: (s) => s('tkl') + s('pd') >= 6, parts: [['Pass breakups per game', 3, pxPerG('pd'), pxF2], ['INTs per game', 2.5, pxPerG('int'), pxF2], ['TFL per game', 0.5, pxPerG('tfl'), pxF2], ['Tackles per game', 0.25, pxPerG('tkl'), pxF1]] },
  S: { min: 'at least 8 tackles', ok: (s) => s('tkl') >= 8, parts: [['INTs per game', 2, pxPerG('int'), pxF2], ['Pass breakups per game', 2, pxPerG('pd'), pxF2], ['Tackles per game', 1, pxPerG('tkl'), pxF1], ['TFL per game', 1, pxPerG('tfl'), pxF2]] },
  DB: { min: '6+ tackles and breakups', ok: (s) => s('tkl') + s('pd') >= 6, parts: [['Pass breakups per game', 2.5, pxPerG('pd'), pxF2], ['INTs per game', 2, pxPerG('int'), pxF2], ['Tackles per game', 0.75, pxPerG('tkl'), pxF1], ['TFL per game', 0.75, pxPerG('tfl'), pxF2]] },
  LB: { min: 'at least 8 tackles', ok: (s) => s('tkl') >= 8, parts: [['Tackles per game', 1.5, pxPerG('tkl'), pxF1], ['TFL per game', 1.5, pxPerG('tfl'), pxF2], ['Sacks per game', 1.5, pxPerG('sacks'), pxF2], ['INTs per game', 1, pxPerG('int'), pxF2], ['Pass breakups per game', 0.75, pxPerG('pd'), pxF2], ['QB hurries per game', 0.5, pxPerG('qbh'), pxF2]] },
  EDGE: { min: 'at least 4 tackles', ok: (s) => s('tkl') >= 4, parts: [['Sacks per game', 2.5, pxPerG('sacks'), pxF2], ['TFL per game', 1.5, pxPerG('tfl'), pxF2], ['QB hurries per game', 1.5, pxPerG('qbh'), pxF2], ['Tackles per game', 0.5, pxPerG('tkl'), pxF1]] },
  DT: { min: 'at least 4 tackles', ok: (s) => s('tkl') >= 4, parts: [['TFL per game', 2, pxPerG('tfl'), pxF2], ['Sacks per game', 1.5, pxPerG('sacks'), pxF2], ['Tackles per game', 1, pxPerG('tkl'), pxF1], ['QB hurries per game', 1, pxPerG('qbh'), pxF2]] },
  DL: { min: 'at least 4 tackles', ok: (s) => s('tkl') >= 4, parts: [['Sacks per game', 2, pxPerG('sacks'), pxF2], ['TFL per game', 2, pxPerG('tfl'), pxF2], ['QB hurries per game', 1, pxPerG('qbh'), pxF2], ['Tackles per game', 0.75, pxPerG('tkl'), pxF1]] },
  K: { min: 'at least 4 FG attempts', ok: (s) => s('fga') >= 4, parts: [['Field goal %', 2, (p, s) => s('fgm') / s('fga'), pxPctF], ['Field goals made per game', 1, pxPerG('fgm'), pxF2]] },
  P: { min: 'at least 8 punts', ok: (s) => s('punts') >= 8, parts: [['Yards per punt', 2.5, (p, s) => s('puntYds') / s('punts'), pxF1], ['Inside-20 rate', 1.5, (p, s) => (s('puntIn20') || 0) / s('punts'), pxPctF], ['Touchback rate', -1, (p, s) => (s('puntTb') || 0) / s('punts'), pxPctF]] },
  ATH: { min: '10+ touches', ok: (s) => s('rushAtt') + s('rec') >= 10, parts: [['Scrimmage yds per game', 1.5, (p, s, gp) => (s('rushYds') + s('recYds')) / gp, pxF1], ['TDs per game', 1, (p, s, gp) => (s('rushTd') + s('recTd')) / gp, pxF2], ['Tackles per game', 0.5, pxPerG('tkl'), pxF1]] },
};
function pxScoreAll(players, S, teamInfo) {
  const gl = Object.values(teamInfo).map(t => t.games || 0).filter(x => x > 0).sort((a, b) => a - b);
  const medG = gl.length ? gl[Math.floor(gl.length / 2)] : 4;
  const buckets = {};
  players.forEach(p => {
    if (p.isHs) return;
    const b = PX_BUCKET[String(p.pos || '').toUpperCase()];
    if (!b) { p.scoreNote = p.grp === 'OL' ? 'No production score for offensive linemen — no individual line stats are published.' : ''; return; }
    p.scoreBucket = b;
    const def = PX_SCORE_DEFS[b];
    const s = (k) => (p.season && S[k] !== undefined ? p.season[S[k]] || 0 : 0);
    if (!p.season || !def.ok(s)) { p.scoreNote = `Not enough playing time yet to score (needs ${def.min}).`; return; }
    const gp = Math.max(1, (teamInfo[p.team] || {}).games || medG);
    const vals = def.parts.map(pt => { const v = pt[2](p, s, gp); return Number.isFinite(v) ? v : null; });
    (buckets[b] = buckets[b] || []).push({ p, vals });
  });
  Object.entries(buckets).forEach(([b, list]) => {
    const { ranked } = pxRankList(list, PX_SCORE_DEFS[b]);
    ranked.forEach(r => {
      r.p.prodPct = r.pct;
      r.p.scoreN = ranked.length;
      r.p.scoreParts = r.parts;
    });
  });
  // Team strength as a percentile of FBS by SP+ (FCS and below: 0), and how
  // far a player's production percentile sits above it.
  const N = Object.values(teamInfo).filter(t => t.sp > 0).length || 136;
  players.forEach(p => {
    if (!p.prodPct) return;
    const t = teamInfo[p.team] || {};
    p.teamStrength = t.sp ? Math.round(100 * (1 - (t.sp - 1) / N)) : 0;
    p.outperf = p.prodPct - p.teamStrength;
  });
  return buckets;
}
// Mid-rank percentile (ties share the middle, so a pile of zeros lands near
// the bottom half rather than looking elite).
function pxMidPct(xs, v) {
  let lo = 0, hi = xs.length;
  while (lo < hi) { const m = (lo + hi) >> 1; if (xs[m] < v) lo = m + 1; else hi = m; }
  let eq = lo; while (eq < xs.length && xs[eq] === v) eq++;
  return ((lo + (eq - lo) / 2) / xs.length) * 100;
}
// Ranks one position's players: each stat becomes a percentile within the
// list, the score is their weighted blend, the percentile is the blend's rank.
// Returns fresh objects (weakest first) so peer subsets don't overwrite the
// players' own all-levels score.
function pxRankList(list, def) {
  const sorted = def.parts.map((_, i) => list.map(r => r.vals[i]).filter(v => v != null).sort((a, c) => a - c));
  const ranked = list.map(r => {
    let num = 0, den = 0;
    const parts = def.parts.map((pt, j) => {
      const v = r.vals[j], xs = sorted[j];
      if (v == null || !xs.length) return null;
      let pp = pxMidPct(xs, v);
      if (pt[1] < 0) pp = 100 - pp;
      num += Math.abs(pt[1]) * pp; den += Math.abs(pt[1]);
      return { label: pt[0], value: pt[3](v), pct: Math.max(1, Math.min(99, Math.round(pp))), weight: pt[1], j, raw: v, med: pt[3](xs[Math.floor(xs.length / 2)]) };
    }).filter(Boolean);
    return { p: r.p, vals: r.vals, parts, comp: den ? num / den : 0 };
  }).sort((a, c) => a.comp - c.comp);
  ranked.forEach((r, i) => { r.pct = Math.max(1, Math.min(99, Math.round(((i + 1) / ranked.length) * 100))); });
  return { ranked, sorted };
}
const pxOrd = (n) => { const v = n % 100; return `${n}${v >= 11 && v <= 13 ? 'th' : ({ 1: 'st', 2: 'nd', 3: 'rd' })[n % 10] || 'th'}`; };
// Same view for a player under the scoring minimum (too few snaps yet): their
// per-game numbers placed among the qualified players — a limited sample.
function pxLimitedView(data, p, scope) {
  const b = p.scoreBucket, def = PX_SCORE_DEFS[b];
  if (!def || !p.season || p.isHs) return null;
  const S = data.S;
  const s = (k) => (S[k] !== undefined ? p.season[S[k]] || 0 : 0);
  const gl = Object.values(data.teamInfo).map(t => t.games || 0).filter(x => x > 0).sort((x, y) => x - y);
  const gp = Math.max(1, (data.teamInfo[p.team] || {}).games || (gl.length ? gl[Math.floor(gl.length / 2)] : 4));
  const vals = def.parts.map(pt => { const v = pt[2](p, s, gp); return Number.isFinite(v) ? v : null; });
  if (!vals.some(v => v)) return null;
  const all = ((data.scoreBuckets || {})[b]) || [];
  const list = scope === 'tier' ? all.filter(r => r.p.tier === p.tier) : scope === 'conf' ? all.filter(r => r.p.conf === p.conf) : all;
  if (!list.length) return null;
  const { ranked, sorted } = pxRankList([...list, { p, vals }], def);
  const i = ranked.findIndex(r => r.p === p);
  return i < 0 ? null : { me: ranked[i], rank: ranked.length - i, n: ranked.length, sorted, limited: true };
}
// A player ranked against one peer group: 'all', 'tier' (same level) or
// 'conf' (same conference).
function pxPeerView(data, p, scope) {
  const all = ((data.scoreBuckets || {})[p.scoreBucket]) || [];
  const list = scope === 'tier' ? all.filter(r => r.p.tier === p.tier) : scope === 'conf' ? all.filter(r => r.p.conf === p.conf) : all;
  if (!list.length) return null;
  const { ranked, sorted } = pxRankList(list, PX_SCORE_DEFS[p.scoreBucket]);
  const i = ranked.findIndex(r => r.p === p);
  return i < 0 ? null : { me: ranked[i], rank: ranked.length - i, n: ranked.length, sorted };
}
// The stat a position's share of team production is measured in.
const PX_SHARE = {
  QB: ['total yards (pass + rush)', (g) => g('passYds') + g('rushYds')],
  RB: ['scrimmage yards', (g) => g('rushYds') + g('recYds')], ATH: ['scrimmage yards', (g) => g('rushYds') + g('recYds')],
  WR: ['receiving yards', (g) => g('recYds')], TE: ['receiving yards', (g) => g('recYds')],
  CB: ['passes defended (breakups + INTs)', (g) => g('pd') + g('int')], S: ['passes defended (breakups + INTs)', (g) => g('pd') + g('int')], DB: ['passes defended (breakups + INTs)', (g) => g('pd') + g('int')],
  LB: ['tackles', (g) => g('tkl')],
  EDGE: ['tackles for loss', (g) => g('tfl')], DT: ['tackles for loss', (g) => g('tfl')], DL: ['tackles for loss', (g) => g('tfl')],
};
function pxTeamShare(data, p) {
  const def = PX_SHARE[p.scoreBucket];
  if (!def || !p.team) return null;
  const { S } = data;
  const val = (pl) => (pl.season ? def[1]((k) => pl.season[S[k]] || 0) : 0);
  let me = 0, room = 0, rest = 0, better = 0;
  const mine = val(p);
  data.players.forEach(pl => {
    if (pl.isHs || pl.team !== p.team) return;
    const v = val(pl);
    if (pl === p) me = v;
    else if (PX_BUCKET[String(pl.pos || '').toUpperCase()] === p.scoreBucket) room += v;
    else rest += v;
    if (pl !== p && v > mine) better++;
  });
  const total = me + room + rest;
  return total > 0 && me > 0 ? { label: def[0], me, room, rest, total, teamRank: better + 1 } : null;
}
const pxScoreTitle = (p) => p.prodPct
  ? `${p.prodPct}th percentile among ${p.scoreN} ${PX_BUCKET_LABEL[p.scoreBucket] || 'players'} — ` + (p.scoreParts || []).slice().sort((a, b) => Math.abs(b.weight) - Math.abs(a.weight)).slice(0, 3).map(x => `${x.label}: ${x.value} (${x.pct}th)`).join(' · ')
  : (p.scoreNote || '');

// Production vs. peers: the score laid out as a small dashboard — headline
// percentile on a segmented meter, what drives it, where the player sits in
// the position's distribution, and their share of the team's output. Peer
// group switches between all levels, the player's level and conference.
function PxMeter({ pct, ticks = 30, h = 30 }) {
  const on = Math.round((pct / 100) * ticks);
  return (
    <div role="img" aria-label={`${pxOrd(pct)} percentile`} style={{ display: "flex", gap: 3, height: h }}>
      {Array.from({ length: ticks }, (_, i) => <span key={i} style={{ flex: 1, borderRadius: 2, background: i < on ? G.green : G.surfaceBorderLight }} />)}
    </div>
  );
}
function PxDonut({ segs, size = 120, stroke = 14, center, sub }) {
  const r = (size - stroke) / 2, C = 2 * Math.PI * r;
  const total = segs.reduce((a, x) => a + x.v, 0) || 1;
  const gap = segs.filter(x => x.v > 0).length > 1 ? 2 : 0;
  let at = 0;
  return (
    <div style={{ position: "relative", width: size, height: size, flexShrink: 0 }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ transform: "rotate(-90deg)", display: "block" }}>
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={G.surfaceBorder} strokeWidth={stroke} />
        {segs.map(x => {
          const len = (x.v / total) * C;
          const el = x.v > 0 && (
            <circle key={x.label} cx={size / 2} cy={size / 2} r={r} fill="none" stroke={x.color} strokeWidth={stroke}
              strokeDasharray={`${Math.max(0, len - gap)} ${C}`} strokeDashoffset={-at}>
              <title>{`${x.label}: ${Math.round((x.v / total) * 100)}%`}</title>
            </circle>
          );
          at += len;
          return el;
        })}
      </svg>
      <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
        <div style={{ fontSize: 23, fontWeight: 800, letterSpacing: "-0.03em", color: G.text, lineHeight: 1.05, fontVariantNumeric: "tabular-nums" }}>{center}</div>
        {sub && <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em", color: G.textTertiary, marginTop: 4 }}>{sub}</div>}
      </div>
    </div>
  );
}
function ProductionReport({ p, data, narrow, inPanel }) {
  const [scope, setScope] = useState('all');
  const [distJ, setDistJ] = useState(null);
  const [hoverBin, setHoverBin] = useState(null);
  useEffect(() => { setScope('all'); setDistJ(null); }, [p.id]);
  const view = useMemo(() => (!data.scoreBuckets ? null : p.prodPct ? pxPeerView(data, p, scope) : pxLimitedView(data, p, scope)), [p, data, scope]);
  const share = useMemo(() => (view && data.players ? pxTeamShare(data, p) : null), [p, data, view]);
  if (p.isHs || p.boardOnly) return null;
  const card = { background: inPanel ? G.surfaceRaised : G.surface, border: `1px solid ${inPanel ? G.surfaceBorder : G.cardBorder}`, boxShadow: inPanel ? 'none' : G.cardShadow, borderRadius: 14, padding: 16, minWidth: 0 };
  const label = (t, extra) => (
    <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 8, marginBottom: 12 }}>
      <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.12em", color: G.textTertiary }}>{t}</div>
      {extra}
    </div>
  );
  if (!view) {
    return p.scoreNote ? <div style={{ ...card, marginTop: inPanel ? 18 : 0, fontSize: 13, color: G.textTertiary }}>{p.scoreNote}</div> : null;
  }
  const b = p.scoreBucket, def = PX_SCORE_DEFS[b];
  const who = PX_BUCKET_LABEL[b] || 'players';
  const scopes = [['all', 'All levels'], p.tier && ['tier', PX_TIER_NAME[p.tier] || p.tier], p.conf && ['conf', p.conf]].filter(Boolean);
  const scopeName = scope === 'tier' ? ` in ${PX_TIER_NAME[p.tier] || p.tier}` : scope === 'conf' ? ` in the ${p.conf}` : '';
  const pct = view.me.pct;
  const parts = view.me.parts.slice().sort((x, y) => Math.abs(y.weight) - Math.abs(x.weight));

  // Headline
  const head = (
    <div style={card}>
      {label('Production percentile', <span style={{ fontSize: 11.5, color: G.textTertiary }}>{data.season} season</span>)}
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap" }}>
        <span style={{ fontSize: 38, fontWeight: 800, letterSpacing: "-0.03em", lineHeight: 1.05, color: G.text, fontVariantNumeric: "tabular-nums" }}>{pxOrd(pct)}</span>
        <span style={{ fontSize: 13, color: G.textSecondary }}>among {view.n} {who}{scopeName}</span>
      </div>
      <div style={{ marginTop: 16 }}><PxMeter pct={pct} /></div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, marginTop: 12, flexWrap: "wrap" }}>
        <span style={{ fontSize: 13, color: G.textSecondary }}>Rank <b style={{ color: G.text, fontVariantNumeric: "tabular-nums" }}>#{view.rank}</b> of {view.n}</span>
        {view.limited && <span style={{ fontSize: 11.5, fontWeight: 700, color: G.yellow }}>Limited sample — under the usual minimum ({def.min})</span>}
        {scope === 'all' && !view.limited && (
          p.outperf >= 40
            ? <span title={`Production percentile ${p.prodPct} vs team strength ${p.teamStrength} (SP+ percentile)`} style={{ fontSize: 11.5, fontWeight: 700, color: G.green, background: G.greenSubtle, border: `1px solid ${G.greenBorder}`, borderRadius: 99, padding: "4px 8px" }}>Outperforming team · +{p.outperf}</span>
            : <span style={{ fontSize: 11.5, color: G.textTertiary }}>Team strength {p.teamStrength ? `${pxOrd(p.teamStrength)} pct (SP+)` : 'outside FBS'} · <span style={{ color: p.outperf > 0 ? G.green : p.outperf < 0 ? G.red : G.textTertiary, fontWeight: 700 }}>{p.outperf > 0 ? '+' : ''}{p.outperf}</span></span>
        )}
      </div>
    </div>
  );

  // What drives it
  const drivers = (
    <div style={card}>
      {label('What drives it', <span style={{ fontSize: 11.5, color: G.textTertiary }}>heaviest weight first</span>)}
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {parts.map(x => (
          <div key={x.label} title={`Counts ×${Math.abs(x.weight)} in the score${x.weight < 0 ? ' (lower is better)' : ''}`}>
            <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
              <span style={{ flex: 1, minWidth: 0, fontSize: 13, color: G.textSecondary }}>{x.label}{x.weight < 0 ? ' · lower is better' : ''}</span>
              <span style={{ fontSize: 15, fontWeight: 700, color: G.text, fontVariantNumeric: "tabular-nums" }}>{x.value}</span>
              <span style={{ fontSize: 11.5, fontWeight: 700, color: x.pct >= 75 ? G.green : G.textTertiary, width: 36, textAlign: "right", fontVariantNumeric: "tabular-nums" }}>{pxOrd(x.pct)}</span>
            </div>
            <div style={{ position: "relative", height: 6, borderRadius: 3, background: G.surfaceBorderLight, marginTop: 6 }}>
              <div style={{ width: `${x.pct}%`, height: "100%", borderRadius: 3, background: x.pct >= 75 ? G.green : G.textTertiary }} />
              <div title="Position median" style={{ position: "absolute", left: "50%", top: -3, bottom: -3, width: 2, marginLeft: -1, background: G.text, opacity: 0.5, borderRadius: 1 }} />
            </div>
            <div style={{ fontSize: 11.5, color: G.textTertiary, marginTop: 4 }}>Median {x.med}</div>
          </div>
        ))}
      </div>
    </div>
  );

  // Distribution of one stat across the peer group
  const pick = parts.find(x => x.j === distJ) || parts.find(x => /per game/i.test(x.label) && x.weight > 0) || parts[0];
  const xs = view.sorted[pick.j] || [];
  const fmt = def.parts[pick.j][3];
  const BINS = 24;
  const lo = xs[0], hi = Math.max(xs[Math.floor(0.98 * (xs.length - 1))], pick.raw);
  const w = (hi - lo) / BINS || 1;
  const binOf = (v) => Math.max(0, Math.min(BINS - 1, Math.floor((v - lo) / w)));
  const counts = Array(BINS).fill(0);
  xs.forEach(v => { counts[binOf(v)]++; });
  const maxC = Math.max(...counts, 1);
  const myBin = binOf(pick.raw);
  const medBin = binOf(xs[Math.floor(xs.length / 2)]);
  const hb = hoverBin != null ? hoverBin : null;
  const dist = (
    <div style={card}>
      {label('Where the player sits', <span style={{ fontSize: 11.5, color: G.textTertiary }}>{xs.length} {who}{scopeName}</span>)}
      <div style={{ display: "flex", gap: 4, flexWrap: "wrap", marginBottom: 12 }}>
        {parts.map(x => (
          <button key={x.j} onClick={() => setDistJ(x.j)}
            style={{ fontFamily: ff, fontSize: 11.5, fontWeight: 600, padding: "4px 8px", borderRadius: 99, cursor: "pointer", border: `1px solid ${x.j === pick.j ? G.greenBorder : G.surfaceBorder}`, background: x.j === pick.j ? G.greenSubtle : 'transparent', color: x.j === pick.j ? G.green : G.textSecondary }}>
            {x.label.replace(/ \(.*\)/, '')}
          </button>
        ))}
      </div>
      <div style={{ fontSize: 13, color: G.textSecondary, minHeight: 20 }}>
        {hb != null
          ? <><b style={{ color: G.text, fontVariantNumeric: "tabular-nums" }}>{counts[hb]}</b> {counts[hb] === 1 ? 'player' : 'players'} at {fmt(lo + hb * w)}–{hb === BINS - 1 ? `${fmt(lo + BINS * w)}+` : fmt(lo + (hb + 1) * w)}</>
          : <><b style={{ color: G.text, fontVariantNumeric: "tabular-nums" }}>{pick.value}</b> — better than {pick.pct}% of {who}{scopeName}</>}
      </div>
      <div onMouseLeave={() => setHoverBin(null)} style={{ position: "relative", display: "flex", alignItems: "flex-end", gap: 2, height: 110, marginTop: 8, borderBottom: `1px solid ${G.surfaceBorderLight}` }}>
        {counts.map((c, i) => (
          <div key={i} onMouseEnter={() => setHoverBin(i)} style={{ flex: 1, height: "100%", display: "flex", alignItems: "flex-end", cursor: "default" }}>
            <div style={{ width: "100%", height: c ? `${Math.max(i === myBin ? 8 : 3, (c / maxC) * 100)}%` : 0, borderRadius: "4px 4px 0 0", background: i === myBin ? G.green : hb === i ? G.textTertiary : G.surfaceBorderLight, transition: "background 0.12s" }} />
          </div>
        ))}
        <div title="Median" style={{ position: "absolute", left: `${((medBin + 0.5) / BINS) * 100}%`, top: 0, bottom: 0, borderLeft: `1px dashed ${G.textTertiary}`, pointerEvents: "none" }} />
      </div>
      <div style={{ position: "relative", height: 16, marginTop: 4 }}>
        <span style={{ position: "absolute", left: `${((myBin + 0.5) / BINS) * 100}%`, transform: `translateX(${myBin > BINS * 0.8 ? '-100%' : myBin < BINS * 0.2 ? '0' : '-50%'})`, marginLeft: myBin > BINS * 0.8 ? 6 : myBin < BINS * 0.2 ? -6 : 0, fontSize: 11.5, fontWeight: 700, color: G.green, whiteSpace: "nowrap" }}>▲ {(p.name || '').split(' ')[0]}</span>
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, color: G.textTertiary, marginTop: 4, fontVariantNumeric: "tabular-nums" }}>
        <span>{fmt(lo)}</span><span>median {pick.med}</span><span>{fmt(hi)}+</span>
      </div>
      {pick.weight < 0 && <div style={{ fontSize: 11.5, color: G.textTertiary, marginTop: 4 }}>Lower is better for this one.</div>}
    </div>
  );

  // Share of team output
  const shareCard = share && (() => {
    const segs = [
      { label: p.name, v: share.me, color: G.green },
      { label: `Other ${who}`, v: share.room, color: G.textTertiary },
      { label: 'Rest of team', v: share.rest, color: G.surfaceBorderLight },
    ];
    const f = (v) => (Number.isInteger(v) ? v.toLocaleString() : (Math.round(v * 10) / 10).toLocaleString());
    return (
      <div style={card}>
        {label(`Share of team ${share.label}`, <span style={{ fontSize: 11.5, color: G.textTertiary, whiteSpace: "nowrap" }}>#{share.teamRank} on team</span>)}
        <div style={{ display: "flex", alignItems: "center", gap: 20, flexWrap: "wrap" }}>
          <PxDonut segs={segs} center={`${Math.round((share.me / share.total) * 100)}%`} sub="of team" />
          <div style={{ flex: 1, minWidth: 180, display: "flex", flexDirection: "column", gap: 8 }}>
            {segs.map(x => (
              <div key={x.label} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13 }}>
                <span style={{ width: 8, height: 8, borderRadius: 4, background: x.color, flexShrink: 0 }} />
                <span style={{ flex: 1, minWidth: 0, color: G.textSecondary, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{x.label}</span>
                <span style={{ fontWeight: 700, color: G.text, fontVariantNumeric: "tabular-nums" }}>{f(x.v)}</span>
                <span style={{ color: G.textTertiary, width: 36, textAlign: "right", fontVariantNumeric: "tabular-nums" }}>{Math.round((x.v / share.total) * 100)}%</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  })();

  return (
    <div style={{ marginTop: inPanel ? 20 : 0 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap", marginBottom: 12 }}>
        <div style={{ fontSize: inPanel ? 15 : 17, fontWeight: 800, letterSpacing: "-0.02em", color: G.text }}>Production vs. peers</div>
        <div style={{ display: "flex", gap: 4, background: G.surfaceRaised, border: `1px solid ${G.surfaceBorder}`, borderRadius: 10, padding: 4 }}>
          {scopes.map(([k, l]) => (
            <button key={k} onClick={() => setScope(k)}
              onMouseEnter={e => { if (scope !== k) e.currentTarget.style.color = G.text; }}
              onMouseLeave={e => { if (scope !== k) e.currentTarget.style.color = G.textSecondary; }}
              style={{ fontFamily: ff, fontSize: 12, fontWeight: 600, padding: "4px 12px", borderRadius: 8, border: "none", cursor: "pointer", background: scope === k ? G.surface : 'transparent', color: scope === k ? G.text : G.textSecondary, boxShadow: scope === k ? G.cardShadow : 'none', whiteSpace: "nowrap" }}>{l}</button>
          ))}
        </div>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: narrow ? "1fr" : "1fr 1fr", gap: 12, alignItems: "start" }}>
        {head}
        {shareCard || drivers}
        {shareCard && drivers}
        {dist}
      </div>
      <div style={{ fontSize: 11.5, color: G.textTertiary, marginTop: 12, lineHeight: 1.5 }}>
        Counting stats are per team game; compared only with {who} who’ve played enough to judge ({def.min}). Source: CollegeFootballData.
      </div>
    </div>
  );
}

// One production number per position group (this season), used to rank a
// player against everyone at his position (Production percentile) and to
// weigh how much of a room's output is leaving. Deliberately simple and
// explainable: yards plus touchdown/turnover credit on offense, tackles
// weighted up for plays behind the line and takeaways on defense.
function pxMetric(grp, v, S) {
  if (!v) return 0;
  const g = (k) => v[S[k]] || 0;
  switch (grp) {
    case 'QB': return g('passYds') + 20 * g('passTd') - 45 * g('passInt') + g('rushYds') + 20 * g('rushTd');
    case 'RB': return g('rushYds') + g('recYds') + 20 * (g('rushTd') + g('recTd'));
    case 'WR': case 'TE': return g('recYds') + 20 * g('recTd');
    case 'DL': return g('tkl') + 3 * g('tfl') + 5 * g('sacks') + 2 * g('qbh') + 2 * g('pd');
    case 'LB': return g('tkl') + 3 * g('tfl') + 4 * g('sacks') + 5 * g('int') + 2 * g('pd');
    case 'DB': return g('tkl') + 6 * g('int') + 3 * g('pd') + 2 * g('tfl');
    case 'K/P': return 3 * g('fgm') + g('punts');
    case 'ATH': return g('rushYds') + g('recYds') + g('tkl');
    default: return 0;
  }
}
const pxLeaving = (pl) => !pl.isHs && (pl.yr || 0) >= 4; // SR / 5th year: likely out of eligibility
// Per position group: every team's room, how much of its production is
// likely leaving (seniors + next-cycle portal entries) and what's coming in
// (committed high school seniors). Cached on the data object per group.
// h = seasons until the player would arrive (1 = next fall; 2 = the fall
// after, for the recruiting class two years out): by then, anyone with
// 5 − h or more years in (listed class) is gone.
function pxTeamNeeds(data, grp, h = 1, fg = grp) {
  data._needs = data._needs || {};
  const ck = `${grp}|${h}|${fg}`;
  if (data._needs[ck]) return data._needs[ck];
  const byTeam = {};
  const get = (t) => (byTeam[t] = byTeam[t] || { name: t, room: [], commits: 0, commitsW: 0, portalOut: 0 });
  // Quality counts, not just bodies: blue-chips (4★+) and proven producers
  // (75th+ percentile) weigh extra as competition.
  const bw = (pl) => 1 + ((pl.stars || 0) >= 4 ? 0.5 : 0) + ((pl.prodPct || 0) >= 75 ? 0.5 : 0);
  data.players.forEach(pl => {
    if (pl.grp !== grp || (fg !== grp && !pxSameRoom(fg, pl))) return;
    if (pl.isHs) { if (pl.commit) { const t = get(pl.commit); t.commits++; t.commitsW += bw(pl); } return; }
    if (pl.team) get(pl.team).room.push(pl);
  });
  (data.portal || []).forEach(e => { if (e.cycle === data.season + 1 && e.grp === grp && e.origin && byTeam[e.origin]) byTeam[e.origin].portalOut++; });
  const out = Object.values(byTeam).filter(t => t.room.length).map(t => {
    const info = data.teamInfo[t.name] || {};
    const total = t.room.reduce((a, pl) => a + (pl.metric || 0), 0);
    const leavers = t.room.filter(pl => !pl.isHs && (pl.yr || 0) >= 5 - h);
    const leavingProd = leavers.reduce((a, pl) => a + (pl.metric || 0), 0);
    // Rooms without countable production (OL, early season) fall back to headcount.
    const share = total > 0 ? leavingProd / total : leavers.length / t.room.length;
    const score = share * 100 + t.portalOut * 8 - t.commits * 10;
    const stayers = t.room.filter(pl => !((pl.yr || 0) >= 5 - h));
    return { name: t.name, tier: info.tier || '', sp: info.sp || 0, logo: info.logo || '', conf: info.conf || '', roomSize: t.room.length, leaving: leavers.length, share, commits: t.commits, portalOut: t.portalOut, score, byCount: !(total > 0),
      staying: stayers.length, stayW: stayers.reduce((a, pl) => a + bw(pl), 0), commitsW: t.commitsW, fg };
  }).sort((a, b) => b.score - a.score || (a.sp || 999) - (b.sp || 999));
  data._needs[ck] = out;
  return out;
}

// Short headers for the per-stat table columns.
const PX_COL = {
  passCmp: 'CMP', passAtt: 'ATT', passYds: 'Pass yds', passTd: 'Pass TD', passInt: 'INT thrown',
  rushAtt: 'CAR', rushYds: 'Rush yds', rushTd: 'Rush TD', rec: 'REC', recYds: 'Rec yds', recTd: 'Rec TD',
  tkl: 'TKL', solo: 'Solo', tfl: 'TFL', sacks: 'Sacks', qbh: 'QB hur', int: 'INT', pd: 'PD',
  fgm: 'FGM', fga: 'FGA', punts: 'Punts', puntYds: 'Punt yds', puntIn20: 'In 20', puntTb: 'TB',
};
// Stat columns shown by default for the selected position groups.
const PX_GROUP_COLS = {
  QB: ['passCmp', 'passAtt', 'passYds', 'passTd', 'passInt', 'rushYds', 'rushTd'],
  RB: ['rushAtt', 'rushYds', 'rushTd', 'rec', 'recYds', 'recTd'],
  WR: ['rec', 'recYds', 'recTd', 'rushYds'], TE: ['rec', 'recYds', 'recTd'],
  DL: ['tkl', 'solo', 'tfl', 'sacks', 'qbh', 'pd'], LB: ['tkl', 'solo', 'tfl', 'sacks', 'int', 'pd'],
  DB: ['tkl', 'solo', 'tfl', 'int', 'pd'], 'K/P': ['fgm', 'fga', 'punts', 'puntYds'], ATH: ['rushYds', 'rec', 'recYds', 'tkl'],
};
const PX_ALL_COLS = ['passYds', 'passTd', 'rushYds', 'rushTd', 'rec', 'recYds', 'recTd', 'tkl', 'tfl', 'sacks', 'int', 'pd'];
const pxMiles = (a, b) => {
  const R = 3959, r = Math.PI / 180;
  const dLat = (b.lat - a.lat) * r, dLng = (b.lng - a.lng) * r;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * r) * Math.cos(b.lat * r) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
};

// Rebuild an out-of-date file (admins only — the server checks), then load
// the new one and hand it to every open page ('mh:prospects').
function pxRefreshIfStale() {
  if (!PROSPECTS.stale || PROSPECTS.building) return;
  PROSPECTS.building = true;
  fetch('/api/prospects?build=1&past=1').then(r => r.json()).then(b => {
    if (!b || !b.ok) return;
    PROSPECTS.stale = false;
    PROSPECTS.data = null;
    return loadProspectData(false).then(d => window.dispatchEvent(new CustomEvent('mh:prospects', { detail: d })));
  }).catch(() => {}).finally(() => { PROSPECTS.building = false; });
}
function useProspectsRefreshed(setter) {
  useEffect(() => {
    const h = (e) => setter(e.detail);
    window.addEventListener('mh:prospects', h);
    return () => window.removeEventListener('mh:prospects', h);
  }, [setter]);
}
function loadProspectData(canBuild, onBuilding) {
  if (PROSPECTS.data) { if (canBuild) pxRefreshIfStale(); return Promise.resolve(PROSPECTS.data); }
  if (PROSPECTS.promise) return PROSPECTS.promise;
  PROSPECTS.promise = (async () => {
    let meta = await fetch('/api/prospects').then(r => r.json());
    const build = (past) => fetch(`/api/prospects?build=1&past=${past}`).then(r => r.json()).catch(() => null);
    if (meta.missing && canBuild) {
      // First run ever: current season only (~30s) so there's something to
      // search; past seasons fill in on later runs.
      onBuilding && onBuilding(true);
      const b = await build(0);
      onBuilding && onBuilding(false);
      if (b && b.ok) meta = await fetch('/api/prospects').then(r => r.json());
    } else if ((meta.careerMissing || []).length && canBuild && !PROSPECTS.building) {
      // Older seasons still loading — show what exists, fill in behind.
      PROSPECTS.building = true;
      build(2).finally(() => { PROSPECTS.building = false; });
    }
    if (!meta.url) throw new Error(meta.missing ? 'The player database hasn’t been built yet — an admin opening this page starts it.' : (meta.error || 'Unavailable'));
    const res = await fetch(meta.url);
    if (!res.ok || !res.body) throw new Error('Couldn’t download the player database.');
    const raw = JSON.parse(await new Response(res.body.pipeThrough(new DecompressionStream('gzip'))).text());
    // File predates newer fields (portal, usage, efficiency, team location
    // and draft…) — rebuild quietly in the background; open pages swap in the
    // new file when it's ready.
    PROSPECTS.stale = (raw.v || 0) < 2 || !raw.teamCols || !(raw.cols || []).includes('ppa') || !(raw.teamCols || []).includes('recPrev') || !(raw.cols || []).includes('depth') || !raw.pathways;
    if (canBuild) pxRefreshIfStale();
    const C = {}; raw.cols.forEach((c, i) => { C[c] = i; });
    const S = {}; raw.stats.forEach((c, i) => { S[c] = i; });
    const cityIndex = {}, confs = new Set(), states = new Set();
    const players = raw.players.map(p => {
      const hs = p[C.kind] === 'hs';
      const t = hs ? [] : (raw.teams[p[C.team]] || []);
      if (t[0]) confs.add(t[0]);
      if (p[C.st]) states.add(p[C.st]);
      if (p[C.city] && p[C.st] && p[C.lat]) cityIndex[`${p[C.city]}, ${p[C.st]}`.toLowerCase()] = { lat: p[C.lat], lng: p[C.lng], label: `${p[C.city]}, ${p[C.st]}` };
      return {
        id: p[C.id], name: `${p[C.first]} ${p[C.last]}`.trim(), team: p[C.team], pos: p[C.pos], grp: pxGroupOf(p[C.pos]),
        ht: p[C.ht], wt: p[C.wt], yr: p[C.yr], city: p[C.city], st: p[C.st], lat: p[C.lat], lng: p[C.lng],
        hs: p[C.hs], stars: p[C.stars], natRank: p[C.natRank],
        conf: t[0] || '', tier: hs ? 'HS' : (t[1] || ''), sp: t[2] || 0, logo: t[4] || '',
        season: p[C.season] || null, career: p[C.career] || null,
        isHs: hs, hsClass: hs ? p[C.recClass] : 0, commit: hs ? p[C.commit] || '' : '', commitLogo: hs && p[C.commit] ? ((raw.teams[p[C.commit]] || [])[4] || '') : '',
        usage: C.usage !== undefined && p[C.usage] ? p[C.usage] : null,
        ppa: C.ppa !== undefined && p[C.ppa] ? p[C.ppa] : null,
        recClass: p[C.recClass] || 0, recType: p[C.recType] || '',
        depth: C.depth !== undefined && p[C.depth] ? p[C.depth] : null, // Ourlads [rank, pos]
      };
    });
    const hsCount = {};
    players.forEach(p => { if (p.hs) hsCount[p.hs] = (hsCount[p.hs] || 0) + 1; });
    // Volume metric: weighs how much of a room's output is leaving (team fit).
    players.forEach(p => { if (!p.isHs) p.metric = pxMetric(p.grp, p.season, S); });
    const tc = raw.teamCols || [];
    const teamInfo = {};
    Object.entries(raw.teams).forEach(([name, t]) => {
      const o = { name };
      tc.forEach((c, i) => { o[c] = t[i]; });
      o.sp = o.spRank || 0;
      teamInfo[name] = o;
    });
    const scoreBuckets = pxScoreAll(players, S, teamInfo);
    const portal = (raw.portal || []).map(e => ({ name: `${e[0]} ${e[1]}`.trim(), pos: e[2], grp: pxGroupOf(e[2]), origin: e[3], dest: e[4], date: e[5], stars: e[6], elig: e[7], cycle: e[8] }));
    PROSPECTS.data = {
      teamInfo, portal, scoreBuckets,
      ts: raw.ts, depthTs: raw.depthTs || 0, pathways: raw.pathways || null, season: raw.season, hsClass: raw.hsClass || 0, careerSeasons: raw.careerSeasons || [], S, players,
      confs: [...confs].sort(), states: [...states].sort(), cityIndex,
      cities: Object.values(cityIndex).map(c => c.label).sort(),
      teams: Object.entries(raw.teams).filter(([name]) => players.some(pl => pl.team === name)).map(([name, t]) => ({ name, conf: t[0], logo: t[4] })).sort((a, b) => a.name.localeCompare(b.name)),
      highSchools: Object.keys(hsCount).sort((a, b) => hsCount[b] - hsCount[a]),
    };
    return PROSPECTS.data;
  })().finally(() => { PROSPECTS.promise = null; });
  return PROSPECTS.promise;
}

// One-line production summary for a player's position group.
function pxKeyLine(p, v, S) {
  if (!v) return '';
  const g = (k) => v[S[k]] || 0;
  const parts = [];
  const add = (n, label) => { if (n) parts.push(`${Math.round(n * 10) / 10} ${label}`); };
  if (p.grp === 'QB') { if (g('passAtt')) parts.push(`${g('passCmp')}/${g('passAtt')}`); add(g('passYds'), 'yds'); add(g('passTd'), 'TD'); add(g('passInt'), 'INT'); add(g('rushYds'), 'rush yds'); }
  else if (p.grp === 'RB') { add(g('rushAtt'), 'car'); add(g('rushYds'), 'yds'); add(g('rushTd'), 'TD'); add(g('rec'), 'rec'); }
  else if (p.grp === 'WR' || p.grp === 'TE') { add(g('rec'), 'rec'); add(g('recYds'), 'yds'); add(g('recTd'), 'TD'); }
  else if (p.grp === 'DL' || p.grp === 'LB' || p.grp === 'DB') { add(g('tkl'), 'tkl'); add(g('tfl'), 'TFL'); add(g('sacks'), 'sk'); add(g('int'), 'INT'); add(g('pd'), 'PD'); }
  else if (p.grp === 'K/P') { if (g('fga')) parts.push(`${g('fgm')}/${g('fga')} FG`); add(g('punts'), 'punts'); }
  else { add(g('rushYds'), 'rush yds'); add(g('rec'), 'rec'); add(g('recYds'), 'rec yds'); add(g('tkl'), 'tkl'); }
  return parts.join(' · ');
}

function ProspectSearch({ isMobile, user, athletes, staff }) {
  const canBuild = !user || user.userRole === 'admin';
  const [data, setData] = useState(PROSPECTS.data);
  const [err, setErr] = useState('');
  const [building, setBuilding] = useState(false);
  const [fRaw, setF] = useCachedState('px.filters', PX_EMPTY);
  const f = { ...PX_EMPTY, ...fRaw };
  const [sort, setSort] = useCachedState('px.sort', { col: '', dir: 'desc' });
  const [shown, setShown] = useState(100);
  const [typed, setTyped] = useState('');
  const [suggestOpen, setSuggestOpen] = useState(false);
  const [colsOpen, setColsOpen] = useState(false);
  const [open, setOpen] = useState(null); // player whose panel is showing
  const q = useDeferredValue(f.q);
  const set = (k, v) => { setF(x => ({ ...PX_EMPTY, ...x, [k]: v })); setShown(100); };
  const setMany = (o) => { setF(x => ({ ...PX_EMPTY, ...x, ...o })); setShown(100); };
  const toggleIn = (k, v) => set(k, (f[k] || []).includes(v) ? f[k].filter(x => x !== v) : [...(f[k] || []), v]);
  const searchRef = useRef();
  const colsRef = useRef();
  useEffect(() => {
    let on = true;
    loadProspectData(canBuild, (b) => on && setBuilding(b)).then(d => on && setData(d)).catch(e => on && setErr(e.message));
    return () => { on = false; };
  }, [canBuild]);
  useProspectsRefreshed(setData);
  useEffect(() => {
    const h = e => {
      if (searchRef.current && !searchRef.current.contains(e.target)) setSuggestOpen(false);
      if (colsRef.current && !colsRef.current.contains(e.target)) setColsOpen(false);
    };
    const k = e => { if (e.key === 'Escape') setOpen(null); };
    document.addEventListener('mousedown', h);
    document.addEventListener('keydown', k);
    return () => { document.removeEventListener('mousedown', h); document.removeEventListener('keydown', k); };
  }, []);

  const ops = useRecruitBoard({ athletes });
  const board = { data: ops.data };
  // Keyed by ESPN id for college players; high schoolers have no ESPN id
  // yet, so they match by name ('n:' keys).
  const ours = useMemo(() => {
    const m = {};
    const nk = (x) => 'n:' + String(x || '').toLowerCase().replace(/[^a-z]/g, '');
    (athletes || []).forEach(a => { if (a.espnId) m[String(a.espnId)] = 'Client'; if (a.level === 'High School' && a.name) m[nk(a.name)] = 'Client'; });
    const d = board.data;
    if (d) {
      const ei = d.headers.findIndex(h => /^espnid$/i.test(String(h).trim()));
      const ni = d.headers.findIndex(h => /^player\s*name$|^name$/i.test(String(h).trim()));
      d.rows.forEach(r => {
        const id = ei >= 0 ? String(r.cells[ei] || '').trim() : '';
        if (id && !m[id]) m[id] = 'On board';
        const n = ni >= 0 ? nk(r.cells[ni]) : '';
        if (n.length > 4 && !m[n]) m[n] = 'On board';
      });
    }
    return m;
  }, [athletes, board.data]);
  const tagFor = (p) => ours[p.isHs ? 'n:' + p.name.toLowerCase().replace(/[^a-z]/g, '') : p.id];

  // Search suggestions: the same text could be a name, a school, a hometown
  // or a high school — let the person say which instead of mixing them.
  const suggestions = useMemo(() => {
    const t = typed.trim().toLowerCase();
    if (!data || t.length < 2) return null;
    const starts = (x) => x.toLowerCase().startsWith(t);
    const has = (x) => x.toLowerCase().includes(t);
    const rank = (list, get) => list.filter(x => has(get(x))).sort((a, b) => (starts(get(b)) ? 1 : 0) - (starts(get(a)) ? 1 : 0)).slice(0, 5);
    return {
      teams: rank(data.teams, x => x.name),
      cities: rank(data.cities, x => x),
      schools: rank(data.highSchools, x => x),
      names: data.players.filter(p => p.name.toLowerCase().includes(t)).length,
    };
  }, [typed, data]);
  const applyName = () => { set('q', typed.trim()); setSuggestOpen(false); };

  const statCols = useMemo(() => {
    if (f.cols) return f.cols;
    const base = f.groups.length ? [...new Set(f.groups.flatMap(g => PX_GROUP_COLS[g] || []))] : PX_ALL_COLS;
    const extra = (f.rules || []).map(r => r.stat).filter(k => k && !base.includes(k));
    return [...base, ...extra];
  }, [f.cols, f.groups, f.rules]);

  const results = useMemo(() => {
    if (!data) return [];
    const { S } = data;
    const ql = String(q || '').trim().toLowerCase();
    const hsl = String(f.hs || '').trim().toLowerCase();
    const nearPt = f.near ? data.cityIndex[String(f.near).trim().toLowerCase()] : null;
    const exactCity = nearPt && !f.miles ? String(f.near).trim().toLowerCase() : '';
    const wMin = parseFloat(f.wtMin) || 0, wMax = parseFloat(f.wtMax) || 0;
    const rules = (f.rules || []).filter(r => r.stat && r.min !== '' && Number.isFinite(parseFloat(r.min)));
    const out = [];
    for (const p of data.players) {
      if (f.team && p.team !== f.team) continue;
      if (f.outperf && !(p.prodPct >= 75 && (p.outperf || 0) >= 40)) continue;
      if (f.groups.length && !f.groups.includes(p.grp)) continue;
      if (f.tiers.length && !f.tiers.includes(p.tier)) continue;
      if (f.conf && p.conf !== f.conf) continue;
      if (f.classes.length && !f.classes.includes(Math.min(p.yr || 0, 5))) continue;
      if (f.htMin && !(p.ht >= f.htMin)) continue;
      if (f.htMax && !(p.ht && p.ht <= f.htMax)) continue;
      if (wMin && !(p.wt >= wMin)) continue;
      if (wMax && !(p.wt && p.wt <= wMax)) continue;
      if (f.st && p.st !== f.st) continue;
      if (exactCity) { if (`${p.city}, ${p.st}`.toLowerCase() !== exactCity) continue; }
      else if (nearPt && !(p.lat && pxMiles(p, nearPt) <= f.miles)) continue;
      if (hsl && !String(p.hs || '').toLowerCase().includes(hsl)) continue;
      if (f.stars && !(p.stars >= f.stars)) continue;
      if (f.spTop && !(p.sp && p.sp <= f.spTop)) continue;
      const v = f.scope === 'career' ? p.career : p.season;
      if (rules.length && !rules.every(r => v && v[S[r.stat]] >= parseFloat(r.min))) continue;
      if (ql && !p.name.toLowerCase().includes(ql)) continue;
      out.push(p);
    }
    const statKey = sort.col && sort.col.startsWith('stat:') ? sort.col.slice(5)
      : !sort.col && rules[0] ? rules[0].stat
      : !sort.col && f.groups.length === 1 ? PX_DEFAULT_SORT[f.groups[0]] : '';
    const dir = sort.col ? (sort.dir === 'asc' ? 1 : -1) : -1;
    const val = (p) => {
      if (statKey) { const v = f.scope === 'career' ? p.career : p.season; return v ? v[S[statKey]] || 0 : -1; }
      switch (sort.col) {
        case 'name': return p.name; case 'pos': return p.pos || ''; case 'yr': return p.yr || 0; case 'team': return p.team || '';
        case 'conf': return p.conf || ''; case 'ht': return p.ht || 0; case 'wt': return p.wt || 0;
        case 'home': return `${p.st} ${p.city}`; case 'hs': return p.hs || '~';
        case 'stars': return p.stars || 0; case 'sp': return p.sp || 999;
        case 'rank': return p.natRank || 99999;
        case 'prod': return p.prodPct || 0;
        case 'commit': return p.commit || '~';
        default: return null;
      }
    };
    if (statKey || sort.col) {
      out.sort((a, b) => {
        const va = val(a), vb = val(b);
        const c = typeof va === 'number' ? va - vb : String(va).localeCompare(String(vb));
        return dir * c || a.name.localeCompare(b.name);
      });
    } else out.sort((a, b) => a.name.localeCompare(b.name));
    return out;
  }, [data, fRaw, q, sort, ours]); // eslint-disable-line

  const clickSort = (col) => setSort(s => s.col === col ? { col, dir: s.dir === 'asc' ? 'desc' : 'asc' } : { col, dir: col.startsWith('stat:') || ['stars', 'ht', 'wt', 'yr'].includes(col) ? 'desc' : 'asc' });
  // Recruit view: national rank matters, college stats don't.
  const hsOnly = f.tiers.length > 0 && f.tiers.every(t => t === 'HS');
  const showRank = f.tiers.includes('HS');
  const shownStatCols = hsOnly ? [] : statCols;
  const activeFilters = JSON.stringify({ ...f, cols: null }) !== JSON.stringify({ ...PX_EMPTY, cols: null });

  const label = (t) => <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.1em", color: G.textTertiary, marginBottom: 6 }}>{t}</div>;
  const chip = (on, text, onClick, key) => (
    <button key={key || text} onClick={onClick}
      style={{ padding: "5px 10px", borderRadius: 99, border: `1px solid ${on ? G.green : G.surfaceBorder}`, background: on ? G.greenSubtle : "transparent", color: on ? G.green : G.textSecondary, fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: ff, whiteSpace: "nowrap" }}>{text}</button>
  );
  const tagChip = (text, onClear, key) => (
    <span key={key} style={{ display: "inline-flex", alignItems: "center", gap: 6, background: G.greenSubtle, color: G.green, borderRadius: 99, padding: "4px 6px 4px 11px", fontSize: 12, fontWeight: 700 }}>
      {text}
      <button onClick={onClear} title="Remove" style={{ background: "none", border: "none", color: G.green, cursor: "pointer", fontSize: 11, padding: "0 3px", fontFamily: ff, lineHeight: 1 }}>✕</button>
    </span>
  );
  const sel = { ...inputBase, padding: "7px 10px", fontSize: 12.5, cursor: "pointer" };
  const inp = { ...inputBase, padding: "7px 10px", fontSize: 12.5 };
  const heights = []; for (let h = 66; h <= 82; h++) heights.push(h);
  const card = { background: G.surface, border: `1px solid ${G.cardBorder}`, boxShadow: G.cardShadow, borderRadius: 14 };
  const headBase = { padding: "10px 12px", fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em", borderBottom: `1px solid ${G.surfaceBorder}`, whiteSpace: "nowrap", cursor: "pointer", userSelect: "none", background: G.surface };
  const th = (col, text, right, extra) => (
    <th key={col} onClick={() => clickSort(col)} style={{ ...headBase, textAlign: right ? "right" : "left", color: sort.col === col ? G.green : G.textTertiary, ...extra }}>
      {text}{sort.col === col ? (sort.dir === 'asc' ? ' ↑' : ' ↓') : ''}
    </th>
  );
  const fmtStat = (n) => (n ? Math.round(n * 10) / 10 : 0);
  const sugRow = (key, icon, text, sub, onPick) => (
    <button key={key} onMouseDown={e => { e.preventDefault(); onPick(); }}
      onMouseEnter={e => e.currentTarget.style.background = G.surfaceRaised} onMouseLeave={e => e.currentTarget.style.background = "transparent"}
      style={{ display: "flex", alignItems: "center", gap: 9, width: "100%", padding: "7px 10px", background: "transparent", border: "none", borderRadius: 8, cursor: "pointer", fontFamily: ff, textAlign: "left" }}>
      <span style={{ width: 20, display: "flex", justifyContent: "center", flexShrink: 0 }}>{icon}</span>
      <span style={{ fontSize: 13, color: G.text, fontWeight: 600, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{text}</span>
      {sub && <span style={{ fontSize: 11.5, color: G.textTertiary, whiteSpace: "nowrap" }}>{sub}</span>}
    </button>
  );
  const sugHead = (t) => <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.1em", color: G.textTertiary, padding: "8px 10px 4px" }}>{t}</div>;
  const glyph = (d) => <svg width="14" height="14" viewBox="0 0 24 24" fill="none"><path d={d} stroke={G.textTertiary} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>;

  const tags = [
    f.q && tagChip(`Name: ${f.q}`, () => { set('q', ''); setTyped(''); }, 'q'),
    f.team && tagChip(`School: ${f.team}`, () => set('team', ''), 'team'),
    f.near && tagChip(f.miles ? `Within ${f.miles} mi of ${f.near}` : `Hometown: ${f.near}`, () => set('near', ''), 'near'),
    f.hs && tagChip(`High school: ${f.hs}`, () => set('hs', ''), 'hs'),
  ].filter(Boolean);

  return (
    <div style={{ maxWidth: 1720, margin: "0 auto", padding: isMobile ? "20px 16px 80px" : "28px 28px 60px" }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
        <div style={{ fontSize: isMobile ? 21 : 24, fontWeight: 800, letterSpacing: "-0.03em", color: G.text }}>Prospect Search</div>
        {data && <div style={{ fontSize: 13, color: G.textTertiary }}>{data.players.filter(x => !x.isHs).length.toLocaleString()} FBS + FCS players{data.hsClass && data.players.some(x => x.isHs) ? ` + ${data.players.filter(x => x.isHs).length.toLocaleString()} high school seniors (class of ${data.hsClass})` : ''} · {data.season} season</div>}
      </div>

      {!data && (
        <div style={{ ...card, marginTop: 16, padding: "40px 20px", textAlign: "center", color: G.textTertiary, fontSize: 13 }}>
          {err ? err : building ? 'Building the player database for the first time — about 30 seconds…' : 'Loading player database…'}
        </div>
      )}

      {data && (<>
        <div style={{ ...card, marginTop: 16, padding: 16 }}>
          <div ref={searchRef} style={{ position: "relative", maxWidth: 560 }}>
            <input value={typed} onChange={e => { setTyped(e.target.value); setSuggestOpen(true); }} onFocus={() => setSuggestOpen(true)}
              onKeyDown={e => { if (e.key === 'Enter') applyName(); }}
              placeholder="Search a player, school, hometown or high school…" style={{ ...inputBase, padding: "10px 14px", fontSize: 13.5 }} />
            {suggestOpen && suggestions && (
              <div style={{ position: "absolute", top: "calc(100% + 6px)", left: 0, right: 0, background: G.surfaceGlass, backdropFilter: "blur(20px)", WebkitBackdropFilter: "blur(20px)", border: `1px solid ${G.surfaceBorderLight}`, borderRadius: 12, boxShadow: G.shadowLg, zIndex: 60, padding: 6, maxHeight: 420, overflowY: "auto" }}>
                {suggestions.names > 0 && sugRow('name', glyph('M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2M12 11a4 4 0 100-8 4 4 0 000 8z'), `Players named “${typed.trim()}”`, `${suggestions.names} match${suggestions.names === 1 ? '' : 'es'} · Enter`, applyName)}
                {suggestions.teams.length > 0 && <>{sugHead('Plays for')}{suggestions.teams.map(t => sugRow('t' + t.name, t.logo ? <TeamLogo url={t.logo} size={18} /> : glyph('M3 21h18M5 21V7l7-4 7 4v14'), t.name, t.conf, () => { set('team', t.name); setTyped(''); setSuggestOpen(false); }))}</>}
                {suggestions.cities.length > 0 && <>{sugHead('Hometown')}{suggestions.cities.map(c => sugRow('c' + c, glyph('M12 22s7-7.1 7-12a7 7 0 10-14 0c0 4.9 7 12 7 12zM12 12a2 2 0 100-4 2 2 0 000 4z'), c, '', () => { setMany({ near: c, miles: 0 }); setTyped(''); setSuggestOpen(false); }))}</>}
                {suggestions.schools.length > 0 && <>{sugHead('High school')}{suggestions.schools.map(h => sugRow('h' + h, glyph('M22 10L12 5 2 10l10 5 10-5zM6 12v5c3 2 9 2 12 0v-5'), h, '', () => { set('hs', h); setTyped(''); setSuggestOpen(false); }))}</>}
                {!suggestions.names && !suggestions.teams.length && !suggestions.cities.length && !suggestions.schools.length && <div style={{ padding: "10px 12px", fontSize: 12.5, color: G.textTertiary }}>Nothing matches “{typed.trim()}”.</div>}
              </div>
            )}
          </div>
          {tags.length > 0 && <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 10 }}>{tags}</div>}

          <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "repeat(auto-fill, minmax(220px, 1fr))", gap: 16, marginTop: 16 }}>
            <div style={{ gridColumn: isMobile ? undefined : "span 2" }}>
              {label('Position')}
              <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>{PX_POS_GROUPS.map(([g]) => chip(f.groups.includes(g), g, () => toggleIn('groups', g)))}</div>
            </div>
            <div>
              {label('Class')}
              <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>{[1, 2, 3, 4, 5].map(y => chip(f.classes.includes(y), PX_CLASS[y], () => toggleIn('classes', y), 'y' + y))}</div>
            </div>
            <div>
              {label('Level')}
              <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>{[...PX_TIERS, ...(data.hsClass ? [['HS', `High school '${String(data.hsClass).slice(2)}`]] : [])].filter(([t]) => t !== 'D2' || data.players.some(p => p.tier === 'D2')).map(([t, l]) => chip(f.tiers.includes(t), l, () => toggleIn('tiers', t), t))}</div>
            </div>
            <div>
              {label('Conference')}
              <select value={f.conf} onChange={e => set('conf', e.target.value)} style={sel}>
                <option value="">All conferences</option>
                {data.confs.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div>
              {label('Team strength (SP+)')}
              <select value={f.spTop} onChange={e => set('spTop', +e.target.value)} style={sel}>
                <option value={0}>Any team</option>
                {[10, 25, 40, 60, 80, 100].map(n => <option key={n} value={n}>Top {n} FBS teams</option>)}
              </select>
            </div>
            <div>
              {label('Height')}
              <div style={{ display: "flex", gap: 6 }}>
                <select value={f.htMin} onChange={e => set('htMin', +e.target.value)} style={sel}><option value={0}>Min</option>{heights.map(h => <option key={h} value={h}>{pxHt(h)}</option>)}</select>
                <select value={f.htMax} onChange={e => set('htMax', +e.target.value)} style={sel}><option value={0}>Max</option>{heights.map(h => <option key={h} value={h}>{pxHt(h)}</option>)}</select>
              </div>
            </div>
            <div>
              {label('Weight (lbs)')}
              <div style={{ display: "flex", gap: 6 }}>
                <input value={f.wtMin} onChange={e => set('wtMin', e.target.value.replace(/\D/g, ''))} placeholder="Min" style={inp} />
                <input value={f.wtMax} onChange={e => set('wtMax', e.target.value.replace(/\D/g, ''))} placeholder="Max" style={inp} />
              </div>
            </div>
            <div>
              {label('Home state')}
              <select value={f.st} onChange={e => set('st', e.target.value)} style={sel}>
                <option value="">Any state</option>
                {data.states.map(x => <option key={x} value={x}>{x}</option>)}
              </select>
            </div>
            <div>
              {label('Hometown area')}
              <div style={{ display: "flex", gap: 6 }}>
                <input value={f.near} onChange={e => set('near', e.target.value)} list="px-cities" placeholder="City, ST" style={inp} />
                <select value={f.miles} onChange={e => set('miles', +e.target.value)} style={{ ...sel, width: 104, flexShrink: 0 }}>
                  <option value={0}>Exact city</option>
                  {[25, 50, 100, 200, 400].map(m => <option key={m} value={m}>{m} mi</option>)}
                </select>
              </div>
              <datalist id="px-cities">{data.cities.map(c => <option key={c} value={c} />)}</datalist>
              {f.near && !data.cityIndex[String(f.near).trim().toLowerCase()] && <div style={{ fontSize: 11.5, color: G.textTertiary, marginTop: 4 }}>Pick a city from the list</div>}
            </div>
            <div>
              {label('Recruiting stars')}
              <select value={f.stars} onChange={e => set('stars', +e.target.value)} style={sel}>
                <option value={0}>Any</option>
                {[2, 3, 4, 5].map(n => <option key={n} value={n}>{'★'.repeat(n)}{n < 5 ? ' or better' : ''}</option>)}
              </select>
            </div>
          </div>

          <div style={{ height: 1, background: G.surfaceBorder, margin: "16px 0" }} />
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
            <span style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.1em", color: G.textTertiary, marginRight: 4 }}>Stats</span>
            {chip(f.outperf, 'Outperforming team', () => set('outperf', !f.outperf), 'op')}
            {chip(f.scope === 'season', `${data.season} season`, () => set('scope', 'season'), 'sc-s')}
            {chip(f.scope === 'career', `Career${data.careerSeasons.length > 1 ? ` (${data.careerSeasons[0]}–${data.careerSeasons[data.careerSeasons.length - 1]})` : ''}`, () => set('scope', 'career'), 'sc-c')}
            <span style={{ width: 8 }} />
            {(f.rules || []).map((r, i) => (
              <span key={i} style={{ display: "inline-flex", alignItems: "center", gap: 6, background: G.surfaceRaised, border: `1px solid ${G.surfaceBorder}`, borderRadius: 10, padding: "3px 6px 3px 8px" }}>
                <select value={r.stat} onChange={e => set('rules', f.rules.map((x, j) => j === i ? { ...x, stat: e.target.value } : x))} style={{ background: "transparent", border: "none", color: G.text, fontSize: 12.5, fontFamily: ff, cursor: "pointer", outline: "none" }}>
                  {PX_STATS.map(([k, l]) => <option key={k} value={k}>{l}</option>)}
                </select>
                <span style={{ fontSize: 12.5, color: G.textTertiary }}>≥</span>
                <input value={r.min} onChange={e => set('rules', f.rules.map((x, j) => j === i ? { ...x, min: e.target.value.replace(/[^\d.]/g, '') } : x))} placeholder="0" style={{ width: 54, background: G.surface, border: `1px solid ${G.surfaceBorder}`, borderRadius: 7, padding: "4px 6px", fontSize: 12.5, color: G.text, fontFamily: ff, outline: "none" }} />
                <button onClick={() => set('rules', f.rules.filter((_, j) => j !== i))} title="Remove" style={{ background: "none", border: "none", color: G.textTertiary, cursor: "pointer", fontSize: 12, padding: "0 2px", fontFamily: ff }}>✕</button>
              </span>
            ))}
            <button onClick={() => set('rules', [...(f.rules || []), { stat: 'rec', min: '' }])}
              style={{ background: "none", border: `1px dashed ${G.surfaceBorderLight}`, borderRadius: 10, padding: "5px 10px", color: G.textSecondary, fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: ff }}>+ Stat filter</button>
            <div style={{ flex: 1 }} />
            {activeFilters && <button onClick={() => { setF(PX_EMPTY); setTyped(''); setSort({ col: '', dir: 'desc' }); setShown(100); }} style={{ background: "none", border: "none", color: G.textTertiary, fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: ff }}>Reset filters</button>}
          </div>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: 10, margin: "18px 2px 10px" }}>
          <div style={{ fontSize: 15, fontWeight: 700, color: G.text }}>{results.length.toLocaleString()} player{results.length === 1 ? '' : 's'}</div>
          {results.length > shown && <div style={{ fontSize: 12, color: G.textTertiary }}>showing the first {shown}</div>}
          <div style={{ flex: 1 }} />
          <div ref={colsRef} style={{ position: "relative" }}>
            <button onClick={() => setColsOpen(v => !v)}
              style={{ display: "flex", alignItems: "center", gap: 6, background: G.surface, border: `1px solid ${G.cardBorder}`, boxShadow: G.cardShadow, borderRadius: 10, padding: "7px 12px", color: G.textSecondary, fontSize: 12.5, fontWeight: 600, cursor: "pointer", fontFamily: ff }}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none"><path d="M4 5h16v14H4zM9.5 5v14M15 5v14" stroke="currentColor" strokeWidth="2" strokeLinejoin="round"/></svg>
              Stat columns <span style={{ fontSize: 9, opacity: 0.6 }}>▾</span>
            </button>
            {colsOpen && (
              <div style={{ position: "absolute", right: 0, top: "calc(100% + 6px)", width: 240, background: G.surfaceGlass, backdropFilter: "blur(20px)", WebkitBackdropFilter: "blur(20px)", border: `1px solid ${G.surfaceBorderLight}`, borderRadius: 12, boxShadow: G.shadowLg, zIndex: 60, padding: 10, maxHeight: 420, overflowY: "auto" }}>
                <div style={{ display: "flex", alignItems: "center", marginBottom: 6 }}>
                  <span style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.1em", color: G.textTertiary }}>{f.cols ? 'Custom' : 'Auto (by position)'}</span>
                  <div style={{ flex: 1 }} />
                  {f.cols && <button onClick={() => set('cols', null)} style={{ background: "none", border: "none", color: G.green, fontSize: 11.5, fontWeight: 700, cursor: "pointer", fontFamily: ff }}>Back to auto</button>}
                </div>
                {PX_STATS.map(([k, l]) => (
                  <label key={k} style={{ display: "flex", alignItems: "center", gap: 9, padding: "4px 2px", fontSize: 13, color: G.text, cursor: "pointer" }}>
                    <input type="checkbox" checked={statCols.includes(k)} onChange={() => set('cols', statCols.includes(k) ? statCols.filter(x => x !== k) : [...statCols, k])} style={{ accentColor: G.green, width: 14, height: 14, margin: 0, cursor: "pointer" }} />
                    {l}
                  </label>
                ))}
              </div>
            )}
          </div>
        </div>

        <div style={{ ...card, overflow: "hidden" }}>
          <div className="mh-hscroll" style={{ overflowX: "auto" }}>
            <table style={{ borderCollapse: "separate", borderSpacing: 0, width: "100%" }}>
              <thead><tr>
                {th('name', 'Player', false, { position: "sticky", left: 0, zIndex: 2 })}{th('pos', 'Pos')}{th('yr', 'Class')}{th('team', 'School')}
                {th('ht', 'Ht', true)}{th('wt', 'Wt', true)}{th('home', 'Hometown')}{th('stars', '★', true)}
                {showRank && th('rank', 'Natl rank', true)}
                {!hsOnly && th('prod', 'Prod %ile', true)}
                {hsOnly && th('commit', 'Committed to')}
                {shownStatCols.map(k => th('stat:' + k, PX_COL[k] || k, true, { borderLeft: k === shownStatCols[0] ? `1px solid ${G.surfaceBorder}` : undefined }))}
              </tr></thead>
              <tbody>
                {results.slice(0, shown).map((p, i, arr) => {
                  const isOpen = open && open.id === p.id;
                  const rowBg = isOpen ? G.greenSubtle : G.surface;
                  const td = { padding: "8px 12px", fontSize: 13, color: G.textSecondary, borderBottom: i < arr.length - 1 ? `1px solid ${G.surfaceBorder}` : "none", whiteSpace: "nowrap", verticalAlign: "middle", background: rowBg };
                  const v = f.scope === 'career' ? p.career : p.season;
                  const tag = tagFor(p);
                  return (
                    <tr key={p.id} onClick={() => setOpen(p)} style={{ cursor: "pointer" }}
                      onMouseEnter={e => { if (!isOpen) [...e.currentTarget.cells].forEach(c => { c.style.background = G.surfaceRaised; }); }}
                      onMouseLeave={e => { [...e.currentTarget.cells].forEach(c => { c.style.background = rowBg; }); }}>
                      <td style={{ ...td, color: G.text, fontWeight: 700, position: "sticky", left: 0, zIndex: 1 }}>
                        <span style={{ display: "inline-flex", alignItems: "center", gap: 9 }}>
                          <Avatar name={p.name} photoUrl={p.isHs ? null : `https://a.espncdn.com/i/headshots/college-football/players/full/${p.id}.png`} size={26} faceZoom />
                          {p.name}
                          {tag && <span style={{ fontSize: 10, fontWeight: 700, color: G.green, background: G.greenSubtle, borderRadius: 99, padding: "2px 7px" }}>{tag}</span>}
                        </span>
                      </td>
                      <td style={td}>{p.pos || '—'}</td>
                      <td style={td}>{p.isHs ? `HS '${String(p.hsClass).slice(2)}` : PX_CLASS[Math.min(p.yr || 0, 5)] || '—'}</td>
                      <td style={{ ...td, maxWidth: 240, overflow: "hidden", textOverflow: "ellipsis" }}>
                        {p.isHs
                          ? <span>{p.hs}{!hsOnly && p.commit && <span style={{ color: G.textTertiary }}> → {p.commit}</span>}</span>
                          : <span style={{ display: "inline-flex", alignItems: "center", gap: 7 }}>{p.logo && <TeamLogo url={p.logo} size={18} />}{p.team}</span>}
                      </td>
                      <td style={{ ...td, textAlign: "right", fontVariantNumeric: "tabular-nums" }}>{pxHt(p.ht) || '—'}</td>
                      <td style={{ ...td, textAlign: "right", fontVariantNumeric: "tabular-nums" }}>{p.wt || '—'}</td>
                      <td style={td}>{p.city ? `${p.city}, ${p.st}` : '—'}</td>
                      <td style={{ ...td, textAlign: "right", color: p.stars >= 4 ? G.green : G.textSecondary, fontWeight: p.stars ? 700 : 400 }}>{p.stars || '—'}</td>
                      {showRank && <td style={{ ...td, textAlign: "right", fontVariantNumeric: "tabular-nums", color: p.natRank ? G.text : G.textTertiary, fontWeight: p.natRank ? 700 : 400 }}>{p.natRank ? `#${p.natRank}` : '—'}</td>}
                      {!hsOnly && <td style={{ ...td, textAlign: "right", fontVariantNumeric: "tabular-nums", color: p.prodPct >= 90 ? G.green : p.prodPct ? G.text : G.textTertiary, fontWeight: p.prodPct ? 700 : 400 }} title={pxScoreTitle(p)}>{p.prodPct ? `${p.prodPct}` : '—'}</td>}
                      {hsOnly && <td style={td}>{p.commit ? <span style={{ display: "inline-flex", alignItems: "center", gap: 7, color: G.text }}>{p.commitLogo && <TeamLogo url={p.commitLogo} size={18} />}{p.commit}</span> : <span style={{ color: G.textTertiary }}>Uncommitted</span>}</td>}
                      {shownStatCols.map((k, ci) => {
                        const n = v ? fmtStat(v[data.S[k]]) : 0;
                        return <td key={k} style={{ ...td, textAlign: "right", fontVariantNumeric: "tabular-nums", color: n ? G.text : G.textTertiary, fontWeight: n ? 700 : 400, borderLeft: ci === 0 ? `1px solid ${G.surfaceBorder}` : undefined }}>{n || '—'}</td>;
                      })}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          {results.length === 0 && <div style={{ padding: "34px 0", textAlign: "center", color: G.textTertiary, fontSize: 13 }}>No players match these filters.</div>}
        </div>
        {results.length > shown && (
          <div style={{ textAlign: "center", marginTop: 14 }}>
            <button onClick={() => setShown(n => n + 200)} style={{ background: G.surface, border: `1px solid ${G.cardBorder}`, boxShadow: G.cardShadow, borderRadius: 10, padding: "9px 18px", color: G.text, fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: ff }}>Show 200 more</button>
          </div>
        )}
        <div style={{ fontSize: 11.5, color: G.textTertiary, marginTop: 14 }}>
          Data from CollegeFootballData.com, refreshed weekly{data.ts ? ` · updated ${new Date(data.ts).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}` : ''}. High school and stars exist for recruited players only; high school seniors have no game stats.
        </div>
      </>)}

      {open && data && <ProspectPanel p={open} data={data} tag={tagFor(open)} isMobile={isMobile} onClose={() => setOpen(null)} ops={ops} staff={staff} user={user} onOpenTeam={(t) => { setOpen(null); openTeamPage(t); }} />}
    </div>
  );
}

// Where a player's position is opening up: every team ranked by the share of
// its room's production that's likely leaving (seniors/5th-years plus
// next-cycle portal entries), minus incoming high school commits.
// ── Team fit model ───────────────────────────────────────────────────────────
// Every team gets a 0–100 score per factor; the player's priorities (0–3 per
// factor, shared by all agents via the FitPrefs tab) weight them into one fit
// score. Level aims at where the player's production says they belong: an
// elite year at a top school keeps them at the top, a weak year points down
// to teams where they'd start.
// Academics — public data only (scripts/academics.js): how selective the
// university is (College Scorecard: average SAT and admission rate) and how
// often its FOOTBALL players graduate (NCAA Graduation Success Rate). Scored
// as percentiles among FBS/FCS schools, selectivity 60% / graduation 40%.
const PX_ACADEMIC = (() => {
  const rows = Object.entries(PX_AC.schools);
  const sorted = (i, flip) => rows.map(([, v]) => v[i]).filter(x => x != null).map(x => (flip ? -x : x)).sort((a, b) => a - b);
  const pctOf = (arr, x) => { let lo = 0; while (lo < arr.length && arr[lo] < x) lo++; let hi = lo; while (hi < arr.length && arr[hi] === x) hi++; return 100 * (lo + hi) / 2 / arr.length; };
  const G = sorted(0), A = sorted(1, true), S = sorted(2);
  const out = {};
  rows.forEach(([n, [gsr, adm, sat]]) => {
    const sel = [sat != null ? pctOf(S, sat) : null, adm != null ? pctOf(A, -adm) : null].filter(x => x != null);
    const selP = sel.length ? sel.reduce((a, b) => a + b, 0) / sel.length : null, gP = gsr != null ? pctOf(G, gsr) : null;
    const score = selP != null && gP != null ? 0.6 * selP + 0.4 * gP : selP != null ? selP : gP;
    out[n] = [Math.round(score), [adm != null ? `Admits ${Math.round(adm)}%` : '', gsr != null ? `${gsr}% football grad rate` : ''].filter(Boolean).join(' · ')];
  });
  return out;
})();
// Scheme: how much a school's offense feeds each position — per game this
// season (QB pass attempts, RB carries + catches, WR / TE catches), as a
// percentile among teams with 3+ games. Coordinators change, so the latest
// season is the one that counts.
const PX_SCHEME_LABEL = { QB: 'QB passes', RB: 'RB touches', WR: 'WR catches', TE: 'TE catches' };
function pxSchemeUse(data) {
  if (data._scheme) return data._scheme;
  const S = data.S || {}, get = (v, k) => (v && S[k] != null ? v[S[k]] || 0 : 0);
  const per = {};
  data.players.forEach(p => {
    if (p.isHs || !p.team || !p.season) return;
    const g = p.grp, v = p.season;
    const n = g === 'QB' ? get(v, 'passAtt') : g === 'RB' ? get(v, 'rushAtt') + get(v, 'rec') : g === 'WR' || g === 'TE' ? get(v, 'rec') : 0;
    if (!n) return;
    const t = per[p.team] || (per[p.team] = {}); t[g] = (t[g] || 0) + n;
  });
  const by = {}, sorted = {};
  Object.entries(per).forEach(([team, o]) => {
    const gm = (data.teamInfo[team] || {}).games || 0;
    if (gm < 3) return;
    by[team] = {}; ['QB', 'RB', 'WR', 'TE'].forEach(g => { by[team][g] = (o[g] || 0) / gm; (sorted[g] = sorted[g] || []).push(by[team][g]); });
  });
  Object.values(sorted).forEach(a => a.sort((x, y) => x - y));
  const avg = {}; Object.entries(sorted).forEach(([g, a]) => { avg[g] = a[Math.floor(a.length / 2)]; });
  data._scheme = { by, sorted, avg };
  return data._scheme;
}
const PX_STARTERS = { QB: 1, RB: 1, WR: 3, TE: 1, OL: 5, DL: 4, LB: 3, DB: 4, 'K/P': 1, ATH: 1, EDGE: 2, DT: 2, CB: 2, S: 2 };
// The room a player actually competes in: edge rushers vs interior linemen,
// corners vs safeties. Teams that list everyone as a generic DL / DB count
// toward both.
const pxFitGroup = (pos) => { const b = PX_BUCKET[String(pos || '').toUpperCase()]; return ['EDGE', 'DT', 'CB', 'S'].includes(b) ? b : pxGroupOf(pos); };
const pxSameRoom = (fg, pl) => {
  if (!['EDGE', 'DT', 'CB', 'S'].includes(fg)) return pl.grp === fg || (fg === 'DL' && pl.grp === 'DL') || (fg === 'DB' && pl.grp === 'DB');
  const g = pxFitGroup(pl.pos);
  return g === fg || (['EDGE', 'DT'].includes(fg) && g === 'DL') || (['CB', 'S'].includes(fg) && g === 'DB');
};
const PX_FIT_FACTORS = [
  ['opp', 'Playing time', 'Would they start: how their production compares with the players who return there, plus how much of the position’s production is leaving (net of commits)'],
  ['level', 'Program level', 'How strong the program is — SP+ this season blended with last season, plus a conference nudge (Power 4 highest). Stronger is always better here; set how much playing somewhere big matters to the player. (Realism — whether they could get there — is handled separately by Aim.)'],
  ['nfl', 'NFL development', 'Players the school sent to the NFL draft at this position in the last five drafts'],
  ['home', 'Close to home', 'Distance from hometown to campus'],
  ['acad', 'Academics', 'How selective the university is (admission rate, SAT) and how often its football players graduate (NCAA)'],
  ['scheme', 'Scheme', 'Offense only: how much the offense feeds the position this season (QB passes, RB touches, WR / TE catches per game)'],
  ['build', 'Roster building', 'How the team added players the last two years. Recruits: teams that sign and develop high schoolers score higher than ones that reload through the portal. College players: the reverse — teams that take transfers'],
  ['pay', 'Earning potential', 'Estimated market value for this player at the school — their budget (The Athletic), the conference’s spending on the position (Opendorse) and the role they’d have (starter / backup / freshman), scaled to ESPN’s 2026 position prices. A reference range, not a salary'],
  ['coach', 'Coach stability', 'Chance the head coach is gone within two years (fired or hired away), from every FBS coaching change since 2020'],
];
const PX_FIT_WEIGHT_LABEL = ['Ignore', 'Some', 'Important', 'Top'];
// What each setting weighs. "Top" also gates: a team that scores badly on a
// top priority has its whole fit pulled down (down to ×0.55 at zero), so
