    if (domain === 'all') {
      if (it.key === 'roster' && lastSide === 'sports') setAgentFilters([]);
      setDomain(lastSide, it.key);
      return;
    }
    if (domain === 'music') { goMusicPage(it.key); return; }
    // Clicking Roster in the nav always shows the full roster — the "my
